/* ============================================================
   MOB SURGE — UI
   ============================================================ */
:root {
  --bg: #080416;
  --bg-2: #120829;
  --ink: #f4f1ff;
  --muted: #a99cc8;
  --cyan: #3ef6ff;
  --cyan-soft: rgba(62, 246, 255, 0.16);
  --pink: #ff3ea5;
  --pink-soft: rgba(255, 62, 165, 0.16);
  --lime: #a7ff4f;
  --gold: #ffc857;
  --violet: #8c5cff;
  --danger: #ff4d63;
  --panel: rgba(16, 9, 36, 0.82);
  --line: rgba(255, 255, 255, 0.12);
  --font: "Inter", "SF Pro Display", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --display: "Arial Black", "Inter", -apple-system, "Segoe UI", sans-serif;
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
}

canvas#game-canvas {
  position: fixed;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  outline: none;
}

button {
  font-family: var(--font);
  border: 0;
  cursor: pointer;
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 3px;
}

.is-hidden { display: none !important; }

/* ---- shared bits ------------------------------------------------ */
.eyebrow {
  margin: 0 0 6px;
  color: var(--cyan);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  text-shadow: 0 0 18px rgba(62, 246, 255, 0.55);
}

.panel {
  position: relative;
  width: min(560px, calc(100vw - 32px));
  max-height: calc(100dvh - 40px - var(--safe-t) - var(--safe-b));
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 28px;
  border-radius: 24px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background:
    linear-gradient(160deg, rgba(35, 20, 70, 0.94), rgba(10, 6, 26, 0.97) 65%),
    var(--panel);
  box-shadow:
    0 30px 90px rgba(0, 0, 0, 0.65),
    inset 0 1px 0 rgba(255, 255, 255, 0.1),
    0 0 0 1px rgba(140, 92, 255, 0.08);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,.2) transparent;
}
.panel::-webkit-scrollbar { width: 8px; }
.panel::-webkit-scrollbar-thumb { background: rgba(255,255,255,.18); border-radius: 8px; }

.panel h2 {
  margin: 0 0 4px;
  font-family: var(--display);
  font-size: clamp(28px, 4vw, 38px);
  font-weight: 900;
  letter-spacing: -0.035em;
  text-transform: uppercase;
}

.panel-sub {
  margin: 0 0 18px;
  color: var(--muted);
  font-size: 13.5px;
  line-height: 1.5;
}

.close-btn {
  position: absolute;
  top: 14px;
  right: 14px;
  z-index: 2;
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: var(--muted);
  font-size: 14px;
  transition: 0.2s;
}
.close-btn:hover { background: rgba(255, 255, 255, 0.14); color: #fff; transform: rotate(90deg); }

/* SVG icon helper */
[data-icon] { display: inline-flex; width: 1.15em; height: 1.15em; }
[data-icon] svg { width: 100%; height: 100%; display: block; }

/* ---- buttons ---------------------------------------------------- */
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 52px;
  padding: 0 26px;
  border-radius: 14px;
  font-weight: 900;
  font-size: 14px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  transition: transform 0.16s ease, box-shadow 0.2s ease, background 0.2s ease, border-color 0.2s;
  user-select: none;
}

.btn:active { transform: translateY(1px) scale(0.985); }

.btn-primary {
  color: #041018;
  background: linear-gradient(100deg, #66fdff 0%, #46e7ff 40%, #79ffb3 100%);
  box-shadow:
    0 8px 28px rgba(62, 246, 255, 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    inset 0 -2px 0 rgba(0, 84, 106, 0.35);
  overflow: hidden;
}
.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow:
    0 14px 40px rgba(62, 246, 255, 0.5),
    inset 0 1px 0 rgba(255, 255, 255, 0.8);
}

.btn-shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 20%, rgba(255,255,255,.55) 45%, transparent 60%);
  transform: translateX(-120%);
  animation: shimmer 3.4s ease-in-out infinite;
}
@keyframes shimmer {
  0%, 55% { transform: translateX(-120%); }
  80%, 100% { transform: translateX(120%); }
}

.btn-ghost {
  color: var(--ink);
  background: rgba(255, 255, 255, 0.055);
  border: 1px solid rgba(255, 255, 255, 0.13);
}
.btn-ghost:hover { background: rgba(255, 255, 255, 0.11); border-color: rgba(255,255,255,.24); }

/* ---- screens & overlays ---------------------------------------- */
.screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(24px + var(--safe-t)) 22px calc(24px + var(--safe-b));
}

.overlay {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: calc(20px + var(--safe-t)) 16px calc(20px + var(--safe-b));
  background: radial-gradient(120% 90% at 50% 45%, rgba(8, 4, 22, 0.42) 0%, rgba(8, 4, 22, 0.82) 60%, rgba(4, 2, 12, 0.94) 100%);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
  animation: overlay-in 0.28s ease both;
}
@keyframes overlay-in { from { opacity: 0; } to { opacity: 1; } }

/* ---- start screen ---------------------------------------------- */
.start-screen {
  background:
    radial-gradient(58% 52% at 50% 46%, rgba(8, 4, 22, 0) 0%, rgba(8, 4, 22, 0.18) 52%, rgba(8, 4, 22, 0.78) 100%),
    linear-gradient(180deg, rgba(8, 4, 22, 0.62) 0%, transparent 22%, transparent 62%, rgba(8, 4, 22, 0.9) 100%);
  z-index: 20;
}

.start-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(680px, 100%);
  text-align: center;
  animation: start-in 0.8s cubic-bezier(.2,.9,.2,1) both;
}
@keyframes start-in {
  from { opacity: 0; transform: translateY(16px) scale(0.985); }
  to { opacity: 1; transform: none; }
}

.badge-row {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 7px 15px;
  margin-bottom: 14px;
  border-radius: 999px;
  border: 1px solid rgba(62, 246, 255, 0.28);
  background: rgba(8, 30, 40, 0.42);
  color: #9fefff;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  box-shadow: 0 0 30px rgba(62, 246, 255, 0.12);
}
.live-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--lime);
  box-shadow: 0 0 10px var(--lime);
  animation: blink 1.8s ease-in-out infinite;
}
@keyframes blink { 0%,100% { opacity: 1; } 50% { opacity: .3; } }

.logo-wrap { position: relative; margin-bottom: 4px; }

.logo {
  margin: 0;
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 0.06em;
  font-family: var(--display);
  font-size: clamp(58px, 11.5vw, 122px);
  line-height: 0.88;
  font-weight: 900;
  letter-spacing: -0.055em;
  text-transform: uppercase;
  transform: skewX(-5deg);
  filter: drop-shadow(0 10px 34px rgba(0, 0, 0, 0.55));
}

.logo-mob {
  color: #fff;
  background: linear-gradient(180deg, #fff 18%, #b7ecff 55%, #55c8ea 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  text-shadow: 0 0 34px rgba(62, 246, 255, 0.35);
}
.logo-surge {
  background: linear-gradient(180deg, #ffd7ee 0%, #ff7bc4 38%, #ff2f9d 65%, #b915ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 0 22px rgba(255, 62, 165, 0.42));
}

.logo-underline {
  width: 72%;
  height: 3px;
  margin: 8px auto 0;
  border-radius: 99px;
  background: linear-gradient(90deg, transparent, var(--cyan) 18%, var(--pink) 55%, transparent 95%);
  box-shadow: 0 0 18px rgba(255, 62, 165, 0.65);
  transform: skewX(-24deg);
  opacity: .95;
}

.tagline {
  margin: 16px 0 22px;
  color: #d6cff2;
  font-size: clamp(14px, 1.7vw, 17px);
  font-weight: 500;
  letter-spacing: 0.04em;
  text-shadow: 0 2px 12px rgba(0,0,0,.6);
}

.start-stats {
  display: flex;
  align-items: stretch;
  gap: 0;
  margin-bottom: 24px;
  padding: 10px 8px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  background: rgba(10, 6, 27, 0.48);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.start-stat {
  min-width: 104px;
  padding: 4px 20px;
  display: flex;
  flex-direction: column;
  gap: 3px;
  border-right: 1px solid rgba(255, 255, 255, 0.08);
}
.start-stat:last-child { border-right: 0; }
.ss-label { color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: 0.2em; }
.start-stat b { font-size: 20px; font-weight: 800; letter-spacing: -0.02em; }
.start-stat .gold { color: var(--gold); text-shadow: 0 0 18px rgba(255, 200, 87, 0.35); }

.btn-play {
  min-width: 248px;
  min-height: 62px;
  font-size: 18px;
  letter-spacing: 0.22em;
  border-radius: 16px;
  animation: play-pulse 2.8s ease-in-out infinite;
}
.btn-play [data-icon] { width: 20px; height: 20px; }
@keyframes play-pulse {
  0%, 100% { box-shadow: 0 8px 28px rgba(62, 246, 255, 0.32), inset 0 1px 0 rgba(255,255,255,.7); }
  50% { box-shadow: 0 12px 46px rgba(62, 246, 255, 0.6), 0 0 70px rgba(62, 246, 255, 0.18), inset 0 1px 0 rgba(255,255,255,.8); }
}

.start-actions {
  display: flex;
  gap: 10px;
  margin-top: 14px;
  flex-wrap: wrap;
  justify-content: center;
}
.start-actions .btn { min-height: 44px; font-size: 11.5px; padding: 0 18px; }
.start-actions [data-icon] { width: 15px; height: 15px; }

.controls-hint {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 22px;
  color: #9d93ba;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.controls-hint kbd {
  display: inline-block;
  padding: 2px 6px;
  margin: 0 1px;
  border-radius: 4px;
  border: 1px solid rgba(255,255,255,.16);
  background: rgba(255,255,255,.06);
  font-family: var(--font);
  font-size: 9.5px;
  color: #d8d1ee;
}
.hint-sep { width: 1px; height: 12px; background: rgba(255,255,255,.16); }

.start-footer {
  position: absolute;
  bottom: calc(12px + var(--safe-b));
  left: 0; right: 0;
  text-align: center;
  color: rgba(200, 190, 225, 0.35);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

/* ---- HUD -------------------------------------------------------- */
.hud {
  position: fixed;
  inset: 0;
  z-index: 10;
  pointer-events: none;
  padding: calc(12px + var(--safe-t)) max(14px, env(safe-area-inset-right)) calc(14px + var(--safe-b)) max(14px, env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  animation: hud-in .45s ease both;
}
@keyframes hud-in { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}
.hud-side { display: flex; align-items: center; gap: 8px; pointer-events: auto; }

.stat-pill {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 54px;
  padding: 0 18px 0 13px;
  border-radius: 16px;
  border: 1px solid rgba(62, 246, 255, 0.22);
  background: linear-gradient(160deg, rgba(17, 30, 52, 0.82), rgba(9, 8, 26, 0.72));
  box-shadow: 0 6px 24px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.08);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.pill-icon {
  width: 28px;
  height: 28px;
  color: var(--cyan);
  filter: drop-shadow(0 0 8px rgba(62,246,255,.55));
}
.pill-value {
  display: flex;
  align-items: baseline;
  gap: 5px;
  font-size: 26px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.03em;
  line-height: 1;
}
.pill-unit { color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: 0.18em; }
.crowd-pill.flash { animation: count-flash .38s ease; }
@keyframes count-flash {
  0% { transform: scale(1); }
  35% { transform: scale(1.09); border-color: rgba(167,255,79,.85); box-shadow: 0 0 40px rgba(167,255,79,.35); }
  100% { transform: scale(1); }
}
.count-pop {
  position: absolute;
  left: 50%;
  top: 100%;
  transform: translate(-50%, 4px);
  color: var(--lime);
  font-size: 16px;
  font-weight: 900;
  letter-spacing: 0.02em;
  text-shadow: 0 0 16px rgba(167, 255, 79, 0.7);
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
}
.count-pop.show { animation: count-pop 1s ease-out both; }
.count-pop.bad { color: var(--danger); text-shadow: 0 0 16px rgba(255,77,99,.7); }
@keyframes count-pop {
  0% { opacity: 0; transform: translate(-50%, 10px) scale(.8); }
  18% { opacity: 1; transform: translate(-50%, -4px) scale(1.1); }
  100% { opacity: 0; transform: translate(-50%, -30px) scale(1); }
}

.coin-pill {
  height: 44px;
  padding: 0 14px;
  border-color: rgba(255, 200, 87, 0.25);
  gap: 8px;
  font-size: 17px;
  font-weight: 900;
  color: var(--gold);
  font-variant-numeric: tabular-nums;
}
.coin-glyph {
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: radial-gradient(circle at 34% 28%, #fff8d6 0%, #ffd35f 38%, #f59818 70%, #a85b00 100%);
  box-shadow: 0 0 10px rgba(255, 200, 87, 0.6), inset 0 -1px 2px rgba(120,60,0,.6);
  display: inline-block;
  flex: none;
}
.coin-glyph.big { width: 30px; height: 30px; }

.icon-btn {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 13px;
  color: #cfc6e8;
  background: rgba(10, 8, 26, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.11);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  transition: .18s;
}
.icon-btn:hover { background: rgba(255, 255, 255, 0.12); color: #fff; }
.icon-btn [data-icon] { width: 18px; height: 18px; }
.icon-btn.muted { color: var(--danger); opacity: .75; }

.hud-center {
  flex: 1;
  max-width: 430px;
  padding-top: 3px;
  text-align: center;
}
.run-line {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  color: #bdb2d8;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.17em;
  text-transform: uppercase;
  text-shadow: 0 1px 8px #000;
}
.run-line b { color: #fff; font-size: 13px; letter-spacing: 0.03em; }
.run-divider { width: 1px; height: 10px; background: rgba(255,255,255,.25); }

.progress-track {
  position: relative;
  height: 7px;
  margin: 7px 0 4px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255,255,255,.07);
  overflow: visible;
}
.progress-fill {
  height: 100%;
  width: 0%;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--cyan), #7effc0 60%, var(--lime));
  box-shadow: 0 0 12px rgba(62,246,255,.5);
  transition: width .2s linear;
}
.progress-marker {
  position: absolute;
  top: 50%;
  left: 100%;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: var(--pink);
  box-shadow: 0 0 14px var(--pink);
}
.run-hint {
  color: rgba(210, 200, 235, 0.66);
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  text-shadow: 0 1px 6px #000;
}

.powerup-bar {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 12px;
  align-items: flex-start;
  pointer-events: none;
  min-height: 0;
}
.power-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  height: 30px;
  padding: 0 11px 0 8px;
  border-radius: 9px;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  border: 1px solid currentColor;
  background: rgba(8, 6, 22, 0.72);
  box-shadow: 0 0 18px -4px currentColor;
  animation: chip-in .25s ease both;
}
@keyframes chip-in { from { opacity: 0; transform: translateX(-8px); } to { opacity: 1; transform: none; } }
.power-chip svg { width: 14px; height: 14px; }
.power-chip .chip-time { opacity: .65; font-variant-numeric: tabular-nums; }
.power-chip .chip-track { width: 32px; height: 3px; border-radius: 9px; background: rgba(255,255,255,.16); overflow: hidden; }
.power-chip .chip-track i { display: block; height: 100%; background: currentColor; border-radius: 9px; }

.battle-hud {
  position: absolute;
  left: 50%;
  bottom: calc(64px + var(--safe-b));
  transform: translateX(-50%);
  width: min(400px, calc(100vw - 40px));
  padding: 10px 14px 11px;
  border-radius: 14px;
  border: 1px solid rgba(255, 77, 99, 0.35);
  background: rgba(20, 4, 14, 0.75);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 8px 32px rgba(0,0,0,.5), 0 0 28px rgba(255,77,99,.12);
  animation: battle-in .25s ease both;
}
@keyframes battle-in { from { opacity:0; transform: translate(-50%, 8px); } to { opacity:1; transform: translate(-50%, 0); } }
.battle-label { text-align: center; color: #ff8e9e; font-size: 9px; font-weight: 900; letter-spacing: .3em; margin-bottom: 6px; animation: battle-pulse 1s ease-in-out infinite; }
@keyframes battle-pulse { 0%,100% { opacity:.7; } 50% { opacity:1; } }
.battle-bar { display: flex; height: 9px; border-radius: 9px; overflow: hidden; background: #2a0a16; gap: 2px; }
.battle-player { background: linear-gradient(90deg, #3ef6ff, #89ffc8); box-shadow: 0 0 12px rgba(62,246,255,.5); transition: width .15s; }
.battle-enemy { flex: 1; background: linear-gradient(90deg, #ff8a5c, #ff3e6c); box-shadow: 0 0 12px rgba(255,62,108,.5); transition: width .15s; }
.battle-counts { display: flex; justify-content: space-between; margin-top: 4px; font-size: 10px; font-weight: 800; font-variant-numeric: tabular-nums; }
.battle-counts #battle-p { color: var(--cyan); }
.battle-counts #battle-e { color: #ff8e9e; }
.battle-vs { color: rgba(255,255,255,.3); font-size: 8px; letter-spacing: .2em; }

.steer-hint {
  position: absolute;
  left: 50%;
  bottom: calc(18px + var(--safe-b));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 14px;
  border-radius: 99px;
  background: rgba(8, 6, 22, 0.55);
  border: 1px solid rgba(255,255,255,.1);
  color: rgba(230, 224, 250, 0.7);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .18em;
  transition: opacity .6s;
}
.steer-hand { color: var(--cyan); font-size: 13px; }

/* ---- screens: pause, over, perk -------------------------------- */
.pause-panel { text-align: center; width: min(420px, calc(100vw - 32px)); }
.pause-stats { display: flex; margin: 18px 0 20px; border-radius: 14px; border: 1px solid var(--line); overflow: hidden; background: rgba(255,255,255,.03); }
.pause-stats div { flex: 1; padding: 12px; display: flex; flex-direction: column; gap: 2px; border-right: 1px solid var(--line); }
.pause-stats div:last-child { border: 0; }
.pause-stats span { color: var(--muted); font-size: 8px; letter-spacing: .18em; font-weight: 800; }
.pause-stats b { font-size: 20px; font-weight: 900; }
.pause-panel .btn { width: 100%; }
.pause-row { display: flex; gap: 10px; margin-top: 10px; }
.pause-row .btn { flex: 1; }

.perk-panel { width: min(740px, calc(100vw - 32px)); text-align: center; }
.perk-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-top: 18px;
}
.perk-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  min-height: 168px;
  padding: 18px 16px 16px;
  text-align: left;
  border-radius: 16px;
  border: 1px solid rgba(255,255,255,.12);
  background: linear-gradient(160deg, rgba(255,255,255,.075), rgba(255,255,255,.02));
  transition: transform .18s ease, border-color .2s, box-shadow .2s;
  overflow: hidden;
}
.perk-card::after {
  content: "";
  position: absolute;
  inset: auto -30% -55% -30%;
  height: 80%;
  background: radial-gradient(circle, var(--perk, var(--cyan)) 0%, transparent 68%);
  opacity: .16;
  pointer-events: none;
}
.perk-card:hover { transform: translateY(-4px); border-color: var(--perk, var(--cyan)); box-shadow: 0 16px 40px -18px var(--perk, var(--cyan)); }
.perk-card:active { transform: translateY(-1px) scale(.99); }
.perk-icon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  color: var(--perk, var(--cyan));
  background: color-mix(in srgb, var(--perk, #3ef6ff) 14%, transparent);
  border: 1px solid color-mix(in srgb, var(--perk, #3ef6ff) 36%, transparent);
  box-shadow: 0 0 22px -6px var(--perk, var(--cyan));
}
.perk-icon svg { width: 22px; height: 22px; }
.perk-name { font-size: 15px; font-weight: 900; letter-spacing: .02em; margin: 2px 0 0; }
.perk-desc { color: var(--muted); font-size: 11.5px; line-height: 1.45; margin: 0; }
.perk-tag { margin-top: auto; color: var(--perk, var(--cyan)); font-size: 8.5px; font-weight: 900; letter-spacing: .16em; text-transform: uppercase; }

.over-panel { text-align: center; width: min(500px, calc(100vw - 32px)); }
.over-title {
  background: linear-gradient(180deg, #fff, #ff9ecb 60%, #ff3e7a);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 0 24px rgba(255,62,122,.3));
}
.new-best {
  display: inline-block;
  margin: 8px 0 0;
  padding: 5px 14px;
  border-radius: 99px;
  color: var(--gold);
  border: 1px solid rgba(255,200,87,.4);
  background: rgba(255,200,87,.08);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: .2em;
  animation: new-best 1.6s ease-in-out infinite;
}
@keyframes new-best { 0%,100% { box-shadow: 0 0 0 rgba(255,200,87,0); } 50% { box-shadow: 0 0 28px rgba(255,200,87,.25); } }

.result-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 7px;
  margin: 18px 0 14px;
}
.result {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 11px 4px;
  border-radius: 12px;
  background: rgba(255,255,255,.045);
  border: 1px solid rgba(255,255,255,.07);
}
.result span { color: var(--muted); font-size: 7.5px; letter-spacing: .15em; font-weight: 800; }
.result b { font-size: 20px; font-weight: 900; font-variant-numeric: tabular-nums; }
.result small { font-size: 10px; color: var(--muted); margin-left: 2px; }

.coin-earn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  margin: 0 0 16px;
  padding: 12px;
  border-radius: 14px;
  background: linear-gradient(90deg, rgba(255,200,87,.03), rgba(255,200,87,.1), rgba(255,200,87,.03));
  border: 1px solid rgba(255,200,87,.2);
}
.coin-earn-value { color: var(--gold); font-size: 26px; font-weight: 900; letter-spacing: -.02em; }
.coin-earn-label { color: var(--muted); font-size: 8px; font-weight: 800; letter-spacing: .18em; }

.btn-revive {
  width: 100%;
  color: #ffe1a6;
  border: 1px solid rgba(255,200,87,.42);
  background: linear-gradient(160deg, rgba(255,200,87,.15), rgba(255,140,0,.06));
  box-shadow: 0 0 30px -12px rgba(255,200,87,.6);
  margin-bottom: 6px;
}
.btn-revive:hover { background: rgba(255,200,87,.2); }
.btn-revive:disabled { opacity: .4; cursor: not-allowed; filter: grayscale(.6); }
.revive-cost { color: var(--gold); font-size: 12px; padding-left: 6px; border-left: 1px solid rgba(255,200,87,.3); }
.revive-note { margin: 0 0 12px; color: var(--muted); font-size: 10px; }
.over-panel > .btn-primary { width: 100%; }
.over-row { display: flex; gap: 10px; margin-top: 10px; }
.over-row .btn { flex: 1; }
.over-row [data-icon] { width: 15px; height: 15px; }

/* ---- upgrades --------------------------------------------------- */
.upgrade-panel { width: min(640px, calc(100vw - 32px)); }
.upgrade-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; padding-right: 44px; }
.wallet {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 13px;
  border-radius: 11px;
  border: 1px solid rgba(255,200,87,.25);
  background: rgba(255,200,87,.07);
  color: var(--gold);
  font-size: 17px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.upgrade-list { display: flex; flex-direction: column; gap: 8px; margin-bottom: 18px; }
.upgrade-row {
  display: grid;
  grid-template-columns: 42px 1fr auto;
  align-items: center;
  gap: 12px;
  padding: 11px 12px;
  border-radius: 13px;
  border: 1px solid rgba(255,255,255,.08);
  background: rgba(255,255,255,.035);
  transition: border-color .2s, background .2s;
}
.upgrade-row:hover { border-color: rgba(255,255,255,.17); background: rgba(255,255,255,.055); }
.upgrade-row.maxed { border-color: rgba(167,255,79,.25); background: rgba(167,255,79,.05); }
.up-icon {
  width: 42px; height: 42px;
  display: grid; place-items: center;
  border-radius: 11px;
  color: var(--up, var(--cyan));
  background: color-mix(in srgb, var(--up, #3ef6ff) 13%, transparent);
  border: 1px solid color-mix(in srgb, var(--up, #3ef6ff) 32%, transparent);
}
.up-icon svg { width: 21px; height: 21px; }
.up-body { min-width: 0; }
.up-name-line { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.up-name { font-size: 13.5px; font-weight: 900; letter-spacing: .01em; }
.up-level { color: var(--muted); font-size: 9px; font-weight: 800; letter-spacing: .12em; }
.up-desc { color: var(--muted); font-size: 10.5px; margin-top: 2px; }
.up-pips { display: flex; gap: 3px; margin-top: 6px; }
.up-pip { width: 12px; height: 4px; border-radius: 3px; background: rgba(255,255,255,.12); }
.up-pip.on { background: var(--up, var(--cyan)); box-shadow: 0 0 8px var(--up, var(--cyan)); }
.up-buy {
  min-width: 92px;
  height: 40px;
  padding: 0 12px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: .06em;
  color: #0a0716;
  background: linear-gradient(140deg, #ffe08a, #ffb62e);
  box-shadow: 0 4px 16px -6px rgba(255,182,46,.8);
  transition: .18s;
}
.up-buy:hover:not(:disabled) { transform: translateY(-1px); filter: brightness(1.08); }
.up-buy:disabled { background: rgba(255,255,255,.07); color: rgba(255,255,255,.3); box-shadow: none; cursor: not-allowed; }
.up-buy .coin-glyph { width: 12px; height: 12px; }
.up-buy.max { background: rgba(167,255,79,.12); color: var(--lime); border: 1px solid rgba(167,255,79,.3); box-shadow: none; }

/* ---- how to play ------------------------------------------------ */
.howto-panel { width: min(600px, calc(100vw - 32px)); }
.howto-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 16px 0 20px; }
.howto-item {
  display: flex;
  gap: 11px;
  padding: 13px;
  border-radius: 13px;
  background: rgba(255,255,255,.035);
  border: 1px solid rgba(255,255,255,.08);
}
.howto-num { color: var(--cyan); font-size: 10px; font-weight: 900; letter-spacing: .1em; padding-top: 2px; opacity: .8; }
.howto-item h3 { margin: 0 0 4px; font-size: 12.5px; font-weight: 900; }
.howto-item p { margin: 0; color: var(--muted); font-size: 10.5px; line-height: 1.45; }
.howto-panel > .btn { width: 100%; }

/* ---- toasts ----------------------------------------------------- */
.toast-layer {
  position: fixed;
  top: calc(78px + var(--safe-t));
  left: 50%;
  transform: translateX(-50%);
  z-index: 60;
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: center;
  pointer-events: none;
  width: max-content;
  max-width: calc(100vw - 32px);
}
.toast {
  padding: 8px 16px;
  border-radius: 99px;
  background: rgba(8, 6, 22, 0.9);
  border: 1px solid rgba(255,255,255,.16);
  color: #eee8ff;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: .08em;
  box-shadow: 0 8px 26px rgba(0,0,0,.5);
  animation: toast-in .25s ease both;
}
.toast.good { border-color: rgba(167,255,79,.4); color: var(--lime); }
.toast.bad { border-color: rgba(255,77,99,.4); color: #ff8e9e; }
.toast.gold { border-color: rgba(255,200,87,.4); color: var(--gold); }
.toast.out { animation: toast-out .3s ease both; }
@keyframes toast-in { from { opacity: 0; transform: translateY(-8px) scale(.96); } to { opacity: 1; transform: none; } }
@keyframes toast-out { to { opacity: 0; transform: translateY(-8px) scale(.96); } }

/* ---- screen flash ---------------------------------------------- */
.screen-flash {
  position: fixed;
  inset: 0;
  z-index: 15;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(circle at 50% 60%, rgba(255,77,99,.5), transparent 68%);
}
.screen-flash.hit { animation: flash-hit .42s ease-out; }
.screen-flash.good { animation: flash-good .5s ease-out; }
@keyframes flash-hit { 0% { opacity: 1; } 100% { opacity: 0; } }
@keyframes flash-good { 0% { opacity: .75; } 100% { opacity: 0; } }
.screen-flash.good { background: radial-gradient(circle at 50% 60%, rgba(167,255,79,.42), transparent 70%); }

/* ---- responsive ------------------------------------------------ */
@media (max-width: 720px) {
  .hud-top { gap: 6px; }
  .hud-side { gap: 6px; }
  .stat-pill { height: 46px; padding: 0 12px 0 9px; border-radius: 13px; gap: 7px; }
  .pill-icon { width: 22px; height: 22px; }
  .pill-value { font-size: 21px; }
  .pill-unit { display: none; }
  .coin-pill { height: 38px; font-size: 14px; padding: 0 10px; }
  .coin-pill .coin-glyph { width: 14px; height: 14px; }
  .icon-btn { width: 38px; height: 38px; border-radius: 11px; }
  .icon-btn [data-icon] { width: 16px; height: 16px; }
  .hud-center { max-width: none; padding-top: 1px; }
  .run-line { font-size: 8.5px; gap: 6px; letter-spacing: .12em; }
  .run-line b { font-size: 11px; }
  .progress-track { height: 6px; margin-top: 5px; }
  .run-hint { font-size: 7px; }
  .powerup-bar { margin-top: 8px; }
  .power-chip { height: 26px; font-size: 8px; }
  .start-stats { width: 100%; justify-content: center; }
  .start-stat { flex: 1; min-width: 0; padding: 4px 10px; }
  .start-stat b { font-size: 17px; }
  .perk-grid { grid-template-columns: 1fr; gap: 8px; }
  .perk-card { min-height: 0; flex-direction: row; align-items: center; gap: 12px; padding: 12px; }
  .perk-icon { flex: none; width: 38px; height: 38px; }
  .perk-card .perk-desc { font-size: 10.5px; }
  .perk-tag { display: none; }
  .perk-name { font-size: 13px; }
  .howto-grid { grid-template-columns: 1fr; }
  .result-grid { grid-template-columns: repeat(2, 1fr); }
  .result b { font-size: 18px; }
  .panel { padding: 22px 18px; border-radius: 20px; }
  .controls-hint { font-size: 9px; gap: 8px; }
  .hint-sep { display: none; }
  .steer-hint { bottom: calc(12px + var(--safe-b)); }
  .battle-hud { bottom: calc(54px + var(--safe-b)); }
}

@media (max-width: 430px) {
  .logo { font-size: clamp(52px, 16vw, 84px); }
  .tagline { margin: 12px 0 16px; }
  .start-stats { padding: 8px 4px; margin-bottom: 18px; }
  .start-stat { padding: 2px 6px; }
  .start-stat b { font-size: 15px; }
  .ss-label { font-size: 8px; }
  .btn-play { min-width: 220px; min-height: 56px; font-size: 16px; }
  .start-actions { width: 100%; }
  .start-actions .btn { flex: 1; }
  .controls-hint { margin-top: 16px; }
  .upgrade-row { grid-template-columns: 36px 1fr auto; gap: 9px; padding: 9px; }
  .up-icon { width: 36px; height: 36px; }
  .up-buy { min-width: 78px; height: 36px; font-size: 10px; }
  .up-desc { font-size: 9.5px; }
  .up-pips { display: none; }
}

@media (max-height: 680px) {
  .badge-row { margin-bottom: 8px; }
  .tagline { margin: 10px 0 14px; }
  .start-stats { margin-bottom: 16px; }
  .controls-hint { margin-top: 14px; }
  .logo { font-size: clamp(48px, 12vh, 88px); }
  .panel { padding: 20px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .01ms !important;
  }
}

