export function defaultSave() {
  return {
    version: 1,
    coins: 0,
    best: 0,
    runs: 0,
    kills: 0,
    upgrades: { squad: 0, strength: 0, magnet: 0, power: 0, bounty: 0 },
    sound: true,
    tutorial: true
  };
}

export function loadSave() {
  const base = defaultSave();
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return base;
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return base;
    return {
      ...base,
      ...parsed,
      upgrades: { ...base.upgrades, ...(parsed.upgrades || {}) },
      coins: Math.max(0, Math.floor(Number(parsed.coins) || 0)),
      best: Math.max(0, Math.floor(Number(parsed.best) || 0)),
      runs: Math.max(0, Math.floor(Number(parsed.runs) || 0)),
      kills: Math.max(0, Math.floor(Number(parsed.kills) || 0))
    };
  } catch {
    return base;
  }
}

let saveTimer = 0;
export function writeSave(save) {
  clearTimeout(saveTimer);
  saveTimer = setTimeout(() => {
    try { localStorage.setItem(KEY, JSON.stringify(save)); } catch { /* private mode */ }
  }, 80);
}

export function flushSave(save) {
  clearTimeout(saveTimer);
  try { localStorage.setItem(KEY, JSON.stringify(save)); } catch { /* ignore */ }
}

export function upgradeCost(def, level) {
  return Math.round(def.baseCost * Math.pow(def.growth, level) / 2) * 2;
}

export function totalUpgradeLevel(save) {
  return Object.values(save.upgrades).reduce((a, b) => a + b, 0);
}

/* Tiny procedural WebAudio engine — no external assets. */
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.muted = false;
    this.musicTimer = null;
    this.musicStep = 0;
    this.started = false;
  }

  init() {
    if (this.ctx) return;
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    this.ctx = new Ctx();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.42;
    this.master.connect(this.ctx.destination);

    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.85;
    this.sfxGain.connect(this.master);

    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.32;
    this.musicGain.connect(this.master);
  }

  unlock() {
    this.init();
    if (!this.ctx) return;
    if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
    this.started = true;
    this.startMusic();
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master && this.ctx) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.42, this.ctx.currentTime, 0.03);
    }
  }

  now() { return this.ctx ? this.ctx.currentTime : 0; }

  tone({ freq = 440, endFreq = null, dur = 0.12, type = 'sine', gain = 0.2, delay = 0, attack = 0.005, dest = null }) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + dur);
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, gain), t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    osc.connect(g);
    g.connect(dest || this.sfxGain);
    osc.start(t);
    osc.stop(t + dur + 0.02);
  }

  noise({ dur = 0.2, gain = 0.18, filter = 900, q = 1, delay = 0, type = 'lowpass' }) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
    const source = this.ctx.createBufferSource();
    source.buffer = buffer;
    const biquad = this.ctx.createBiquadFilter();
    biquad.type = type;
    biquad.frequency.setValueAtTime(filter, t);
    biquad.Q.value = q;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(gain, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    source.connect(biquad);
    biquad.connect(g);
    g.connect(this.sfxGain);
    source.start(t);
  }

  click() {
    this.tone({ freq: 620, endFreq: 880, dur: 0.06, type: 'triangle', gain: 0.1 });
  }

  coin() {
    this.tone({ freq: 1180, endFreq: 1680, dur: 0.09, type: 'sine', gain: 0.13 });
    this.tone({ freq: 1760, endFreq: 2200, dur: 0.07, type: 'triangle', gain: 0.055, delay: 0.035 });
  }

  recruit() {
    this.tone({ freq: 380, endFreq: 590, dur: 0.1, type: 'triangle', gain: 0.12 });
    this.tone({ freq: 590, endFreq: 880, dur: 0.12, type: 'sine', gain: 0.1, delay: 0.07 });
  }

  gate(positive = true, big = false) {
    if (positive) {
      const base = big ? 392 : 330;
      [0, 4, 7, 12].forEach((semi, i) => {
        this.tone({ freq: base * Math.pow(2, semi / 12), dur: 0.13, type: 'triangle', gain: 0.1 - i * 0.012, delay: i * 0.045 });
      });
      this.noise({ dur: 0.24, gain: 0.05, filter: 3200, type: 'highpass', delay: 0.02 });
    } else {
      [0, -3, -7].forEach((semi, i) => {
        this.tone({ freq: 330 * Math.pow(2, semi / 12), dur: 0.15, type: 'sawtooth', gain: 0.065, delay: i * 0.06 });
      });
    }
  }

  hit() {
    this.noise({ dur: 0.26, gain: 0.26, filter: 520 });
    this.tone({ freq: 160, endFreq: 48, dur: 0.25, type: 'sine', gain: 0.22 });
  }

  slice() {
    this.noise({ dur: 0.12, gain: 0.14, filter: 2600, type: 'highpass' });
    this.tone({ freq: 900, endFreq: 260, dur: 0.12, type: 'sawtooth', gain: 0.06 });
  }

  shield() {
    this.tone({ freq: 520, endFreq: 1040, dur: 0.3, type: 'sine', gain: 0.14 });
    this.tone({ freq: 780, endFreq: 1560, dur: 0.35, type: 'triangle', gain: 0.08, delay: 0.05 });
  }

  powerup() {
    [0, 5, 9, 12, 16].forEach((s, i) => {
      this.tone({ freq: 440 * Math.pow(2, s / 12), dur: 0.16, type: 'triangle', gain: 0.09, delay: i * 0.055 });
    });
  }

  clash() {
    this.noise({ dur: 0.2, gain: 0.18, filter: 1400, q: 2 });
    this.tone({ freq: 220, endFreq: 90, dur: 0.18, type: 'square', gain: 0.06 });
  }

  win() {
    [0, 4, 7, 12].forEach((s, i) => {
      this.tone({ freq: 523 * Math.pow(2, s / 12), dur: 0.18, type: 'triangle', gain: 0.1, delay: i * 0.08 });
    });
  }

  fail() {
    [0, -2, -5, -12].forEach((s, i) => {
      this.tone({ freq: 330 * Math.pow(2, s / 12), dur: 0.35, type: 'sawtooth', gain: 0.075, delay: i * 0.15 });
    });
    this.noise({ dur: 0.7, gain: 0.16, filter: 300 });
  }

  perk() {
    [0, 7, 12].forEach((s, i) => {
      this.tone({ freq: 660 * Math.pow(2, s / 12), dur: 0.22, type: 'sine', gain: 0.11, delay: i * 0.09 });
    });
  }

  startMusic() {
    if (this.musicTimer || !this.ctx) return;
    this.musicStep = 0;
    this.musicTimer = setInterval(() => this.tickMusic(), 300);
  }

  stopMusic() {
    clearInterval(this.musicTimer);
    this.musicTimer = null;
  }

  tickMusic() {
    if (!this.ctx || this.muted) return;
    const step = this.musicStep++;
    // Slow minor-key synthwave arpeggio.
    const roots = [110, 110, 130.81, 98];
    const root = roots[Math.floor(step / 8) % roots.length];
    const pattern = [0, 7, 12, 15, 19, 15, 12, 7];
    const semi = pattern[step % 8];
    const freq = root * Math.pow(2, semi / 12);
    this.tone({ freq, dur: 0.34, type: 'triangle', gain: 0.052, dest: this.musicGain, attack: 0.02 });
    if (step % 8 === 0) {
      this.tone({ freq: root / 2, dur: 1.8, type: 'sine', gain: 0.07, dest: this.musicGain, attack: 0.12 });
      this.tone({ freq: root * 1.5, dur: 1.4, type: 'sine', gain: 0.025, dest: this.musicGain, attack: 0.2 });
    }
    if (step % 4 === 2) {
      this.noise({ dur: 0.04, gain: 0.022, filter: 7000, type: 'highpass' });
    }
  }
}

import * as THREE from 'three';

/* ---------- procedural textures ---------- */
const texCache = new Map();

export function radialTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)', size = 128) {
  const key = `radial|${inner}|${outer}|${size}`;
  if (texCache.has(key)) return texCache.get(key);
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, inner);
  g.addColorStop(0.45, inner);
  g.addColorStop(1, outer);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  texCache.set(key, tex);
  return tex;
}

export function ringTexture(color = '255,255,255') {
  const key = `ring|${color}`;
  if (texCache.has(key)) return texCache.get(key);
  const size = 256;
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  ctx.strokeStyle = `rgba(${color},1)`;
  ctx.lineWidth = 8;
  ctx.shadowColor = `rgba(${color},1)`;
  ctx.shadowBlur = 22;
  ctx.beginPath();
  ctx.arc(size / 2, size / 2, size / 2 - 26, 0, Math.PI * 2);
  ctx.stroke();
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  texCache.set(key, tex);
  return tex;
}

export function textTexture(text, {
  color = '#ffffff',
  glow = 'rgba(255,255,255,0.8)',
  font = '900',
  width = 512,
  height = 256,
  size = 150,
  sub = '',
  subColor = 'rgba(255,255,255,0.7)',
  bg = null,
  border = null
} = {}) {
  const key = `text|${text}|${color}|${glow}|${width}|${height}|${size}|${sub}|${subColor}|${bg}|${border}`;
  if (texCache.has(key)) return texCache.get(key);
  const c = document.createElement('canvas');
  c.width = width;
  c.height = height;
  const ctx = c.getContext('2d');

  if (bg) {
    ctx.fillStyle = bg;
    roundRect(ctx, 6, 6, width - 12, height - 12, 34);
    ctx.fill();
  }
  if (border) {
    ctx.strokeStyle = border;
    ctx.lineWidth = 7;
    ctx.shadowColor = border;
    ctx.shadowBlur = 22;
    roundRect(ctx, 10, 10, width - 20, height - 20, 30);
    ctx.stroke();
    ctx.shadowBlur = 0;
  }

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = `${font} ${size}px "Arial Black", "Inter", system-ui, sans-serif`;
  ctx.shadowColor = glow;
  ctx.shadowBlur = 28;
  ctx.fillStyle = color;
  const mainY = sub ? height * 0.43 : height * 0.5;
  ctx.fillText(text, width / 2, mainY);

  if (sub) {
    ctx.font = `800 ${Math.round(size * 0.17)}px "Inter", system-ui, sans-serif`;
    ctx.shadowBlur = 10;
    ctx.fillStyle = subColor;
    ctx.fillText(sub, width / 2, height * 0.75);
  }

  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  texCache.set(key, tex);
  return tex;
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

/* ---------- particles ---------- */
const MAX_PARTICLES = 700;
const _color = new THREE.Color();

export class Particles {
  constructor(scene) {
    this.count = 0;
    this.pos = new Float32Array(MAX_PARTICLES * 3);
    this.col = new Float32Array(MAX_PARTICLES * 3);
    this.vel = new Float32Array(MAX_PARTICLES * 3);
    this.life = new Float32Array(MAX_PARTICLES);
    this.maxLife = new Float32Array(MAX_PARTICLES);
    this.grav = new Float32Array(MAX_PARTICLES);
    this.drag = new Float32Array(MAX_PARTICLES);
    this.baseCol = new Float32Array(MAX_PARTICLES * 3);

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setAttribute('color', new THREE.BufferAttribute(this.col, 3).setUsage(THREE.DynamicDrawUsage));
    geo.setDrawRange(0, 0);
    const mat = new THREE.PointsMaterial({
      size: 0.35,
      map: radialTexture('rgba(255,255,255,1)', 'rgba(255,255,255,0)', 64),
      vertexColors: true,
      transparent: true,
      opacity: 0.95,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      sizeAttenuation: true
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    this.points.renderOrder = 5;
    scene.add(this.points);
    this.geo = geo;
  }

  spawn(x, y, z, color, {
    speed = 4, spread = 1, life = 0.8, gravity = -8, drag = 1.6, size = 1
  } = {}) {
    if (this.count >= MAX_PARTICLES) return;
    const i = this.count++;
    const theta = Math.random() * Math.PI * 2;
    const up = Math.random() * 2 - 1;
    const mag = speed * (0.35 + Math.random() * 0.9);
    this.pos[i * 3] = x;
    this.pos[i * 3 + 1] = y;
    this.pos[i * 3 + 2] = z;
    this.vel[i * 3] = Math.cos(theta) * mag * spread;
    this.vel[i * 3 + 1] = up * mag * 0.8 + speed * 0.35;
    this.vel[i * 3 + 2] = Math.sin(theta) * mag * spread;
    this.life[i] = life * (0.7 + Math.random() * 0.6);
    this.maxLife[i] = this.life[i];
    this.grav[i] = gravity;
    this.drag[i] = drag;
    _color.set(color);
    this.baseCol[i * 3] = _color.r;
    this.baseCol[i * 3 + 1] = _color.g;
    this.baseCol[i * 3 + 2] = _color.b;
  }

  burst(x, y, z, color, count = 14, opts = {}) {
    for (let i = 0; i < count; i++) this.spawn(x, y, z, color, opts);
  }

  update(dt) {
    let i = 0;
    while (i < this.count) {
      this.life[i] -= dt;
      if (this.life[i] <= 0) {
        const last = --this.count;
        if (i !== last) {
          for (let k = 0; k < 3; k++) {
            this.pos[i * 3 + k] = this.pos[last * 3 + k];
            this.vel[i * 3 + k] = this.vel[last * 3 + k];
            this.baseCol[i * 3 + k] = this.baseCol[last * 3 + k];
          }
          this.life[i] = this.life[last];
          this.maxLife[i] = this.maxLife[last];
          this.grav[i] = this.grav[last];
          this.drag[i] = this.drag[last];
        }
        continue;
      }
      const d = Math.max(0, 1 - this.drag[i] * dt);
      this.vel[i * 3] *= d;
      this.vel[i * 3 + 1] = this.vel[i * 3 + 1] * d + this.grav[i] * dt;
      this.vel[i * 3 + 2] *= d;
      this.pos[i * 3] += this.vel[i * 3] * dt;
      this.pos[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
      this.pos[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
      if (this.pos[i * 3 + 1] < 0.03) {
        this.pos[i * 3 + 1] = 0.03;
        this.vel[i * 3 + 1] *= -0.28;
      }
      const t = Math.max(0, this.life[i] / this.maxLife[i]);
      this.col[i * 3] = this.baseCol[i * 3] * t;
      this.col[i * 3 + 1] = this.baseCol[i * 3 + 1] * t;
      this.col[i * 3 + 2] = this.baseCol[i * 3 + 2] * t;
      i++;
    }
    this.geo.setDrawRange(0, this.count);
    this.geo.attributes.position.needsUpdate = true;
    this.geo.attributes.color.needsUpdate = true;
  }
}

/* ---------- shockwave rings ---------- */
export class Shockwaves {
  constructor(scene) {
    this.scene = scene;
    this.items = [];
    this.pool = [];
    for (let i = 0; i < 12; i++) {
      const mat = new THREE.SpriteMaterial({
        map: ringTexture('255,255,255'),
        color: 0xffffff,
        transparent: true,
        opacity: 0,
        blending: THREE.AdditiveBlending,
        depthWrite: false,
        depthTest: false
      });
      const sprite = new THREE.Sprite(mat);
      sprite.visible = false;
      sprite.renderOrder = 6;
      scene.add(sprite);
      this.pool.push(sprite);
    }
  }

  ring(x, y, z, color = 0x3ef6ff, { scale = 1, life = 0.6, growth = 12 } = {}) {
    const s = this.pool.pop();
    if (!s) return;
    s.visible = true;
    s.position.set(x, y, z);
    s.scale.setScalar(scale);
    s.material.color.set(color);
    s.material.opacity = 0.95;
    this.items.push({ sprite: s, life, max: life, growth, base: scale });
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const it = this.items[i];
      it.life -= dt;
      const t = 1 - it.life / it.max;
      if (it.life <= 0) {
        it.sprite.visible = false;
        it.sprite.material.opacity = 0;
        this.pool.push(it.sprite);
        this.items.splice(i, 1);
        continue;
      }
      it.sprite.scale.setScalar(it.base + it.growth * t);
      it.sprite.material.opacity = (1 - t) * 0.85;
    }
  }
}

/* ---------- floating 3D text ---------- */
export class Floaters {
  constructor(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.items = [];
    this.pool = [];
    this.matCache = new Map();
  }

  float(text, x, y, z, color = '#ffffff', { scale = 2.6, life = 1.1, rise = 2.2, glow = 'rgba(255,255,255,.7)', sub = '' } = {}) {
    const tex = textTexture(text, { color, glow, size: 170, sub, width: 512, height: sub ? 300 : 256 });
    let sprite = this.pool.pop();
    if (!sprite) {
      const mat = new THREE.SpriteMaterial({
        map: tex,
        transparent: true,
        depthWrite: false,
        depthTest: false,
        opacity: 1
      });
      sprite = new THREE.Sprite(mat);
      sprite.renderOrder = 7;
      this.scene.add(sprite);
    } else {
      sprite.material.map = tex;
      sprite.material.needsUpdate = true;
    }
    sprite.visible = true;
    sprite.position.set(x, y, z);
    sprite.scale.set(scale, scale * (sub ? 0.6 : 0.5), 1);
    sprite.material.opacity = 1;
    sprite.material.color.set(0xffffff);
    this.items.push({ sprite, life, max: life, rise, baseY: y });
  }

  update(dt) {
    for (let i = this.items.length - 1; i >= 0; i--) {
      const it = this.items[i];
      it.life -= dt;
      const t = 1 - it.life / it.max;
      it.sprite.position.y = it.baseY + it.rise * Math.min(1, t * 1.6);
      const fade = t < 0.7 ? 1 : 1 - (t - 0.7) / 0.3;
      it.sprite.material.opacity = Math.max(0, fade);
      if (it.life <= 0) {
        it.sprite.visible = false;
        this.pool.push(it.sprite);
        this.items.splice(i, 1);
      }
    }
  }

  clear() {
    for (const it of this.items) {
      it.sprite.visible = false;
      this.pool.push(it.sprite);
    }
    this.items.length = 0;
  }
}

import * as THREE from 'three';
import { radialTexture, ringTexture } from './fx.js';

const _dummy = new THREE.Object3D();
const _q = new THREE.Quaternion();
const _e = new THREE.Euler();
const _col = new THREE.Color();

const GEO = {
  body: new THREE.CapsuleGeometry(0.155, 0.25, 4, 8),
  head: new THREE.SphereGeometry(0.15, 10, 8),
  cap: new THREE.ConeGeometry(0.135, 0.19, 6, 1),
  leg: new THREE.BoxGeometry(0.075, 0.24, 0.075),
  shadow: new THREE.CircleGeometry(0.3, 12).rotateX(-Math.PI / 2)
};

const PLAYER_PALETTE = ['#32f2ff', '#39c9ff', '#6d9cff', '#45f7c3', '#9a7dff', '#4ee6ff'];
const ENEMY_PALETTE = ['#ff3e7a', '#ff5a4a', '#ff7a2f', '#e12bff', '#ff2e5f', '#ff8b3d'];
const SKIN = ['#f7c9a3', '#e8b08a', '#c98d63', '#8d5a3b', '#f2d2b8', '#b97a54'];
const CAPS = ['#9ffbff', '#7de8ff', '#c0b3ff', '#9dffd3'];

function buildOffsets(max) {
  const out = [{ x: 0, z: 0 }];
  let ring = 1;
  while (out.length < max) {
    const n = 6 * ring;
    const radius = ring * 0.54;
    const start = ring * 0.35;
    for (let i = 0; i < n && out.length < max; i++) {
      const a = start + (i / n) * Math.PI * 2;
      out.push({ x: Math.cos(a) * radius, z: Math.sin(a) * radius * 0.92 });
    }
    ring++;
  }
  return out;
}

export class Crowd {
  constructor(scene, { team = 'player', max = 300 } = {}) {
    this.scene = scene;
    this.team = team;
    this.max = max;
    this.offsets = buildOffsets(max);
    this.count = 0;
    this.visual = 0;
    this.targetVisual = 0;
    this.x = 0;
    this.z = 0;
    this.spread = 1;
    this.radius = 1.2;
    this.pop = 1;
    this.time = 0;
    this.hidden = false;
    this.bigEvery = team === 'enemy' ? 9 : 13;

    const palette = team === 'player' ? PLAYER_PALETTE : ENEMY_PALETTE;

    const bodyMat = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.4,
      metalness: 0.18,
      emissive: new THREE.Color(team === 'player' ? 0x043c44 : 0x3c041c),
      emissiveIntensity: 0.7,
      flatShading: false
    });
    const headMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.62, metalness: 0.02 });
    const capMat = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.25,
      metalness: 0.5,
      emissive: new THREE.Color(team === 'player' ? 0x1b8c9c : 0x8c1b3f),
      emissiveIntensity: 0.85
    });
    const legMat = new THREE.MeshStandardMaterial({ color: 0x141428, roughness: 0.7, metalness: 0.1 });
    const shadowMat = new THREE.MeshBasicMaterial({
      color: 0x000000,
      transparent: true,
      opacity: team === 'player' ? 0.32 : 0.36,
      depthWrite: false
    });

    const mk = (geo, mat, count) => {
      const m = new THREE.InstancedMesh(geo, mat, count);
      m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      m.frustumCulled = false;
      m.count = 0;
      m.renderOrder = 2;
      scene.add(m);
      return m;
    };

    this.body = mk(GEO.body, bodyMat, max);
    this.head = mk(GEO.head, headMat, max);
    this.cap = mk(GEO.cap, capMat, max);
    this.legs = mk(GEO.leg, legMat, max * 2);
    this.shadows = mk(GEO.shadow, shadowMat, max);
    this.shadows.renderOrder = 1;

    this.phases = new Float32Array(max);
    this.speeds = new Float32Array(max);
    this.sizes = new Float32Array(max);
    for (let i = 0; i < max; i++) {
      this.phases[i] = Math.random() * Math.PI * 2;
      this.speeds[i] = 0.85 + Math.random() * 0.45;
      this.sizes[i] = i % this.bigEvery === this.bigEvery - 1 ? (team === 'enemy' ? 1.3 : 1.16) : 1;
    }

    // instance colors
    for (let i = 0; i < max; i++) {
      _col.set(palette[i % palette.length]);
      this.body.setColorAt(i, _col);
      _col.set(palette[(i + 2) % palette.length]).multiplyScalar(1.12);
      this.cap.setColorAt(i, _col);
      _col.set(SKIN[i % SKIN.length]);
      this.head.setColorAt(i, _col);
    }
    if (this.body.instanceColor) this.body.instanceColor.needsUpdate = true;
    if (this.cap.instanceColor) this.cap.instanceColor.needsUpdate = true;
    if (this.head.instanceColor) this.head.instanceColor.needsUpdate = true;

    // aura
    this.aura = new THREE.Group();
    this.aura.visible = false;
    const ringMat = new THREE.MeshBasicMaterial({
      color: 0x3ef6ff,
      transparent: true,
      opacity: 0.55,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide
    });
    this.auraRing = new THREE.Mesh(new THREE.RingGeometry(1.5, 2.1, 64), ringMat);
    this.auraRing.rotation.x = -Math.PI / 2;
    this.auraRing.position.y = 0.05;
    this.aura.add(this.auraRing);

    const domeMat = new THREE.MeshBasicMaterial({
      color: 0x3ef6ff,
      transparent: true,
      opacity: 0.055,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide
    });
    this.auraDome = new THREE.Mesh(new THREE.SphereGeometry(1, 20, 14), domeMat);
    this.auraDome.scale.set(2.1, 1.15, 2.1);
    this.aura.add(this.auraDome);
    this.auraGroup = this.aura;
    scene.add(this.aura);

    // soft ground glow for player squad
    if (team === 'player') {
      const glowMat = new THREE.SpriteMaterial({
        map: radialTexture('rgba(62,246,255,0.5)', 'rgba(62,246,255,0)', 128),
        transparent: true,
        opacity: 0.6,
        blending: THREE.AdditiveBlending,
        depthWrite: false
      });
      this.glow = new THREE.Sprite(glowMat);
      this.glow.scale.set(7, 3.2, 1);
      scene.add(this.glow);
    }
  }

  setCount(n) {
    const prev = this.count;
    this.count = Math.max(0, Math.floor(n));
    this.targetVisual = Math.min(this.count, this.max);
    if (this.targetVisual > prev) this.pop = Math.min(1.35, this.pop + 0.09);
    if (this.count === 0) this.visual = 0;
  }

  setPosition(x, z) {
    this.x = x;
    this.z = z;
  }

  setVisible(v) {
    this.hidden = !v;
    this.body.visible = v;
    this.head.visible = v;
    this.cap.visible = v;
    this.legs.visible = v;
    this.shadows.visible = v;
    this.aura.visible = v && this._auraOn;
    if (this.glow) this.glow.visible = v;
  }

  setAura(color, strength = 1) {
    this._auraOn = strength > 0;
    this.aura.visible = this._auraOn && !this.hidden;
    if (!this._auraOn) return;
    this.auraRing.material.color.set(color);
    this.auraDome.material.color.set(color);
    this.auraRing.material.opacity = 0.35 + 0.28 * strength;
    this.auraDome.material.opacity = 0.035 + 0.04 * strength;
  }

  clearAura() {
    this._auraOn = false;
    this.aura.visible = false;
  }

  update(dt, time, speed = 18) {
    this.time = time;
    const target = this.targetVisual;
    const lerp = 1 - Math.pow(0.0001, dt);
    this.visual += (target - this.visual) * Math.min(1, lerp * 1.6);
    if (this.visual < 0.05) this.visual = 0;
    const n = Math.min(this.max, Math.round(this.visual));
    this.pop += (1 - this.pop) * Math.min(1, dt * 8);

    if (!this.hidden && n > 0) {
      this.body.count = n;
      this.head.count = n;
      this.cap.count = n;
      this.legs.count = n * 2;
      this.shadows.count = n;

      const spread = 0.82 + Math.min(0.45, this.visual * 0.0019) + (this.pop - 1) * 0.6;
      this.spread = spread;
      let maxR = 0.6;
      const runSpeed = 10 + Math.min(8, speed * 0.2);

      for (let i = 0; i < n; i++) {
        const off = this.offsets[i];
        const phase = this.phases[i];
        const size = this.sizes[i];
        const wob = Math.sin(time * 2.1 + phase) * 0.035;
        const ox = off.x * spread + wob;
        const oz = off.z * spread + Math.cos(time * 1.7 + phase) * 0.035;
        const r = Math.hypot(ox, oz);
        if (r > maxR) maxR = r;

        const bob = Math.abs(Math.sin(time * runSpeed * 0.7 + phase)) * 0.075 * (0.8 + speed * 0.006);
        const sway = Math.sin(time * 4.4 + phase) * 0.035;
        const x = this.x + ox;
        const z = this.z + oz;
        const yBase = 0;

        // body
        _dummy.position.set(x + sway, yBase + 0.46 + bob, z);
        _e.set(Math.sin(time * runSpeed + phase) * 0.055, 0, Math.sin(time * 2.3 + phase) * 0.045);
        _q.setFromEuler(_e);
        _dummy.quaternion.copy(_q);
        _dummy.scale.set(size, size, size);
        _dummy.updateMatrix();
        this.body.setMatrixAt(i, _dummy.matrix);

        // head
        _dummy.position.set(x + sway * 1.3, yBase + 0.83 + bob, z);
        _e.set(0, Math.sin(time * 1.5 + phase) * 0.3, 0);
        _dummy.quaternion.setFromEuler(_e);
        _dummy.scale.set(size, size, size);
        _dummy.updateMatrix();
        this.head.setMatrixAt(i, _dummy.matrix);

        // cap
        _dummy.position.set(x + sway * 1.3, yBase + 0.99 + bob, z);
        _e.set(Math.sin(time * runSpeed + phase) * 0.08, 0, 0);
        _dummy.quaternion.setFromEuler(_e);
        _dummy.scale.set(size, size, size);
        _dummy.updateMatrix();
        this.cap.setMatrixAt(i, _dummy.matrix);

        // legs
        const swing = Math.sin(time * runSpeed + phase) * 0.85;
        for (let l = 0; l < 2; l++) {
          _dummy.position.set(x + (l === 0 ? -0.085 : 0.085) * size, yBase + 0.16 + bob * 0.35, z);
          _e.set(swing * (l === 0 ? 1 : -1), 0, 0);
          _dummy.quaternion.setFromEuler(_e);
          _dummy.scale.set(size, size, size);
          _dummy.updateMatrix();
          this.legs.setMatrixAt(i * 2 + l, _dummy.matrix);
        }

        // shadow
        _dummy.position.set(x + 0.03, 0.022, z + 0.04);
        _dummy.quaternion.identity();
        _dummy.scale.setScalar(size * (1 + bob * 0.45));
        _dummy.updateMatrix();
        this.shadows.setMatrixAt(i, _dummy.matrix);
      }

      this.body.instanceMatrix.needsUpdate = true;
      this.head.instanceMatrix.needsUpdate = true;
      this.cap.instanceMatrix.needsUpdate = true;
      this.legs.instanceMatrix.needsUpdate = true;
      this.shadows.instanceMatrix.needsUpdate = true;
      this.radius = maxR + 0.35;
    } else if (this.hidden || n === 0) {
      this.body.count = 0;
      this.head.count = 0;
      this.cap.count = 0;
      this.legs.count = 0;
      this.shadows.count = 0;
      this.radius = 0.6;
    }

    if (this.glow) {
      const s = Math.max(2.2, this.radius * 2.6);
      this.glow.position.set(this.x, 0.06, this.z);
      this.glow.scale.set(s, s * 0.42, 1);
      this.glow.material.opacity = this.hidden ? 0 : 0.38;
    }

    if (this._auraOn) {
      const pulse = 1 + Math.sin(time * 5) * 0.07;
      this.aura.position.set(this.x, 0, this.z);
      const s = Math.max(1.3, this.radius * 1.15);
      this.auraRing.scale.set(s, s, s);
      this.auraDome.scale.set(s * 1.5, Math.max(1, s * 0.72), s * 1.5);
      this.auraRing.material.opacity = (0.32 + Math.sin(time * 7) * 0.08) * pulse;
    }
  }

  randomUnitPosition() {
    if (this.count === 0) return new THREE.Vector3(this.x, 0.6, this.z);
    const i = Math.floor(Math.random() * Math.min(this.count, this.max));
    const off = this.offsets[i];
    return new THREE.Vector3(this.x + off.x * this.spread, 0.5 + Math.random() * 0.5, this.z + off.z * this.spread);
  }

  dispose() {
    for (const m of [this.body, this.head, this.cap, this.legs, this.shadows]) {
      this.scene.remove(m);
      m.dispose();
    }
    this.scene.remove(this.aura);
    if (this.glow) this.scene.remove(this.glow);
  }
}

/* A floating count banner for enemy mobs */
export class CountBanner {
  constructor(scene) {
    this.scene = scene;
    const canvas = document.createElement('canvas');
    canvas.width = 256;
    canvas.height = 128;
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.texture = new THREE.CanvasTexture(canvas);
    this.texture.colorSpace = THREE.SRGBColorSpace;
    this.sprite = new THREE.Sprite(new THREE.SpriteMaterial({
      map: this.texture,
      transparent: true,
      depthWrite: false,
      depthTest: false
    }));
    this.sprite.scale.set(3.4, 1.7, 1);
    this.sprite.visible = false;
    this.sprite.renderOrder = 6;
    scene.add(this.sprite);
    this.value = -1;
    this.color = '#ff6b8a';
  }

  set(count, color = '#ff6b8a') {
    if (count === this.value && color === this.color) return;
    this.value = count;
    this.color = color;
    const ctx = this.ctx;
    const w = 256, h = 128;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = 'rgba(20,4,14,0.82)';
    ctx.strokeStyle = color;
    ctx.lineWidth = 5;
    ctx.shadowColor = color;
    ctx.shadowBlur = 18;
    roundRect(ctx, 10, 26, w - 20, 76, 26);
    ctx.fill();
    ctx.stroke();
    ctx.shadowBlur = 0;
    ctx.font = '900 54px "Arial Black", Inter, system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(String(count), w / 2, 65);
    ctx.font = '800 17px Inter, system-ui, sans-serif';
    ctx.fillStyle = 'rgba(255,255,255,.72)';
    ctx.fillText('RIVAL MOB', w / 2, 100);
    this.texture.needsUpdate = true;
  }

  position(x, y, z) {
    this.sprite.position.set(x, y, z);
  }

  setVisible(v) { this.sprite.visible = v; }
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

import * as THREE from 'three';
import { radialTexture } from './fx.js';

function makeTrackTexture() {
  const w = 512, h = 1024;
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  const ctx = c.getContext('2d');

  const base = ctx.createLinearGradient(0, 0, w, 0);
  base.addColorStop(0, '#0b0820');
  base.addColorStop(0.5, '#121031');
  base.addColorStop(1, '#0b0820');
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, w, h);

  // subtle hex-ish tile grid
  ctx.strokeStyle = 'rgba(120, 100, 200, 0.075)';
  ctx.lineWidth = 1;
  for (let y = 0; y <= h; y += 64) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(w, y);
    ctx.stroke();
  }
  for (let x = 0; x <= w; x += 64) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, h);
    ctx.stroke();
  }

  // outer edge glow strips
  const edge = (x0, dir, colorA, colorB) => {
    const g = ctx.createLinearGradient(x0, 0, x0 + dir * 46, 0);
    g.addColorStop(0, colorA);
    g.addColorStop(0.28, colorB);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.fillRect(Math.min(x0, x0 + dir * 46), 0, 46, h);
  };
  edge(0, 1, 'rgba(62,246,255,0.95)', 'rgba(62,246,255,0.12)');
  edge(w, -1, 'rgba(255,62,165,0.95)', 'rgba(255,62,165,0.12)');

  // lane dashes
  ctx.strokeStyle = 'rgba(150, 140, 255, 0.35)';
  ctx.lineWidth = 4;
  ctx.setLineDash([34, 52]);
  for (const x of [w * 0.25, w * 0.75]) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, h);
    ctx.stroke();
  }
  ctx.setLineDash([]);

  // center energy line
  const cg = ctx.createLinearGradient(0, 0, 0, h);
  cg.addColorStop(0, 'rgba(255,255,255,0)');
  cg.addColorStop(0.5, 'rgba(180,160,255,0.28)');
  cg.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = cg;
  ctx.fillRect(w / 2 - 1.5, 0, 3, h);

  // chevrons
  ctx.strokeStyle = 'rgba(62, 246, 255, 0.28)';
  ctx.lineWidth = 6;
  ctx.lineCap = 'round';
  for (let y = 40; y < h; y += 128) {
    ctx.beginPath();
    ctx.moveTo(w / 2 - 34, y + 26);
    ctx.lineTo(w / 2, y);
    ctx.lineTo(w / 2 + 34, y + 26);
    ctx.stroke();
  }

  // little sparkles
  for (let i = 0; i < 70; i++) {
    ctx.fillStyle = `rgba(${140 + Math.random() * 100},${160 + Math.random() * 80},255,${0.04 + Math.random() * 0.1})`;
    const s = 1 + Math.random() * 2.5;
    ctx.fillRect(Math.random() * w, Math.random() * h, s, s);
  }

  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(1, 26);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

function makeGridTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 256;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, 256, 256);
  ctx.strokeStyle = 'rgba(255, 62, 165, 0.65)';
  ctx.lineWidth = 2;
  ctx.shadowColor = 'rgba(255,62,165,0.8)';
  ctx.shadowBlur = 8;
  ctx.strokeRect(1, 1, 254, 254);
  ctx.strokeStyle = 'rgba(62, 246, 255, 0.22)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(128, 0); ctx.lineTo(128, 256);
  ctx.moveTo(0, 128); ctx.lineTo(256, 128);
  ctx.stroke();
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(80, 80);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

function makeBuildingTexture(hue = 280) {
  const c = document.createElement('canvas');
  c.width = 128; c.height = 256;
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#0a0718';
  ctx.fillRect(0, 0, 128, 256);
  const colors = ['#ffd28a', '#7de8ff', '#ff8bd6', '#a6a0ff'];
  for (let y = 8; y < 250; y += 13) {
    for (let x = 8; x < 122; x += 12) {
      if (Math.random() < 0.42) {
        ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)];
        ctx.globalAlpha = 0.3 + Math.random() * 0.65;
        ctx.fillRect(x, y, 5, 5);
      }
    }
  }
  ctx.globalAlpha = 1;
  const grad = ctx.createLinearGradient(0, 0, 0, 256);
  grad.addColorStop(0, `rgba(${hue === 280 ? '120,60,255' : '255,60,150'},0.18)`);
  grad.addColorStop(1, 'rgba(0,0,0,0.3)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 128, 256);
  const tex = new THREE.CanvasTexture(c);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(1, 2);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeCloudTexture() {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 128;
  const ctx = c.getContext('2d');
  for (let i = 0; i < 7; i++) {
    const x = 40 + Math.random() * 176;
    const y = 45 + Math.random() * 40;
    const r = 24 + Math.random() * 36;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(255, 220, 255, 0.32)');
    g.addColorStop(0.55, 'rgba(230, 160, 255, 0.13)');
    g.addColorStop(1, 'rgba(200, 120, 255, 0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export class World {
  constructor(scene) {
    this.scene = scene;
    this.items = [];
    this.menuDrift = 0;
    this._buildSky();
    this._buildTrack();
    this._buildRails();
    this._buildArches();
    this._buildScenery();
    this._buildDust();
    this._buildLights();
  }

  _buildSky() {
    const geo = new THREE.SphereGeometry(620, 32, 24);
    const mat = new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        topColor: { value: new THREE.Color('#0b0524') },
        midColor: { value: new THREE.Color('#3a1154') },
        lowColor: { value: new THREE.Color('#b13363') },
        horizonColor: { value: new THREE.Color('#ff9b62') },
        sunDir: { value: new THREE.Vector3(-0.22, 0.09, -1).normalize() }
      },
      vertexShader: `
        varying vec3 vDir;
        void main() {
          vDir = normalize(position);
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform vec3 topColor; uniform vec3 midColor; uniform vec3 lowColor; uniform vec3 horizonColor; uniform vec3 sunDir;
        varying vec3 vDir;
        void main() {
          float h = clamp(vDir.y, -0.2, 1.0);
          vec3 col = mix(horizonColor, lowColor, smoothstep(-0.01, 0.12, h));
          col = mix(col, midColor, smoothstep(0.08, 0.38, h));
          col = mix(col, topColor, smoothstep(0.42, 0.95, h));
          float sun = max(dot(normalize(vDir), sunDir), 0.0);
          col += vec3(1.0, 0.52, 0.22) * pow(sun, 160.0) * 1.3;
          col += vec3(1.0, 0.40, 0.40) * pow(sun, 16.0) * 0.22;
          // subtle horizontal synth bands near the horizon
          float band = sin(h * 160.0) * 0.5 + 0.5;
          col += vec3(1.0, 0.25, 0.5) * band * 0.012 * smoothstep(0.25, 0.0, abs(h - 0.07));
          gl_FragColor = vec4(col, 1.0);
        }
      `
    });
    this.sky = new THREE.Mesh(geo, mat);
    this.sky.position.y = 30;
    this.scene.add(this.sky);

    // sun halo
    const sunMat = new THREE.SpriteMaterial({
      map: radialTexture('rgba(255,220,170,0.95)', 'rgba(255,110,60,0)', 256),
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      opacity: 0.95
    });
    this.sun = new THREE.Sprite(sunMat);
    this.sun.scale.set(180, 180, 1);
    this.sun.position.set(-140, 62, -520);
    this.scene.add(this.sun);

    const discMat = new THREE.SpriteMaterial({
      map: radialTexture('rgba(255,236,205,1)', 'rgba(255,140,80,0.6)', 128),
      transparent: true,
      blending: THREE.AdditiveBlending,
      depthWrite: false
    });
    this.sunDisc = new THREE.Sprite(discMat);
    this.sunDisc.scale.set(42, 42, 1);
    this.sunDisc.position.set(-140, 62, -519);
    this.scene.add(this.sunDisc);

    // stars
    const starCount = 420;
    const pos = new Float32Array(starCount * 3);
    const col = new Float32Array(starCount * 3);
    for (let i = 0; i < starCount; i++) {
      const r = 420 + Math.random() * 140;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(Math.random() * 0.85 + 0.12);
      pos[i * 3] = Math.sin(phi) * Math.cos(theta) * r;
      pos[i * 3 + 1] = Math.cos(phi) * r + 80;
      pos[i * 3 + 2] = Math.sin(phi) * Math.sin(theta) * r;
      const c = new THREE.Color().setHSL(0.55 + Math.random() * 0.25, 0.5, 0.7 + Math.random() * 0.3);
      col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
    }
    const sg = new THREE.BufferGeometry();
    sg.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    sg.setAttribute('color', new THREE.BufferAttribute(col, 3));
    this.stars = new THREE.Points(sg, new THREE.PointsMaterial({
      size: 1.4, vertexColors: true, transparent: true, opacity: 0.85,
      depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true
    }));
    this.scene.add(this.stars);

    // clouds
    this.clouds = [];
    const cloudTex = makeCloudTexture();
    for (let i = 0; i < 9; i++) {
      const mat = new THREE.SpriteMaterial({
        map: cloudTex, transparent: true, depthWrite: false,
        opacity: 0.22 + Math.random() * 0.22, blending: THREE.AdditiveBlending
      });
      const s = new THREE.Sprite(mat);
      s.position.set((Math.random() - 0.5) * 420, 45 + Math.random() * 80, -200 - Math.random() * 280);
      const sc = 70 + Math.random() * 90;
      s.scale.set(sc, sc * 0.42, 1);
      this.scene.add(s);
      this.clouds.push({ sprite: s, drift: 0.4 + Math.random() * 1.1 });
    }
  }

  _buildTrack() {
    this.trackTex = makeTrackTexture();
    const geo = new THREE.PlaneGeometry(18.6, 620);
    const mat = new THREE.MeshStandardMaterial({
      map: this.trackTex,
      roughness: 0.82,
      metalness: 0.18,
      color: 0xffffff,
      emissive: 0x080411,
      emissiveIntensity: 0.4
    });
    this.track = new THREE.Mesh(geo, mat);
    this.track.rotation.x = -Math.PI / 2;
    this.track.position.set(0, 0, -270);
    this.scene.add(this.track);

    // underside / base slab
    const slab = new THREE.Mesh(
      new THREE.BoxGeometry(19.6, 1.2, 620),
      new THREE.MeshStandardMaterial({ color: 0x0c0820, roughness: 0.5, metalness: 0.5 })
    );
    slab.position.set(0, -0.72, -270);
    this.scene.add(slab);

    // void grid below
    const grid = new THREE.Mesh(
      new THREE.PlaneGeometry(900, 900),
      new THREE.MeshBasicMaterial({
        map: makeGridTexture(),
        transparent: true,
        opacity: 0.3,
        blending: THREE.AdditiveBlending,
        depthWrite: false
      })
    );
    grid.rotation.x = -Math.PI / 2;
    grid.position.set(0, -10, -260);
    this.scene.add(grid);
    this.grid = grid;

    const voidPlane = new THREE.Mesh(
      new THREE.PlaneGeometry(2000, 2000),
      new THREE.MeshBasicMaterial({ color: 0x06030f })
    );
    voidPlane.rotation.x = -Math.PI / 2;
    voidPlane.position.set(0, -11, -260);
    this.scene.add(voidPlane);
  }

  _buildRails() {
    const railMat = new THREE.MeshStandardMaterial({ color: 0x191232, roughness: 0.4, metalness: 0.7 });
    const neonCyan = new THREE.MeshBasicMaterial({ color: 0x3ef6ff });
    const neonPink = new THREE.MeshBasicMaterial({ color: 0xff3ea5 });
    for (const side of [-1, 1]) {
      const rail = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.34, 620), railMat);
      rail.position.set(side * 9.65, 0.1, -270);
      this.scene.add(rail);
      const glow = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.09, 620), side < 0 ? neonCyan : neonPink);
      glow.position.set(side * 9.65, 0.31, -270);
      this.scene.add(glow);

      const wall = new THREE.Mesh(
        new THREE.PlaneGeometry(620, 1.8),
        new THREE.MeshBasicMaterial({
          color: side < 0 ? 0x3ef6ff : 0xff3ea5,
          transparent: true,
          opacity: 0.05,
          blending: THREE.AdditiveBlending,
          side: THREE.DoubleSide,
          depthWrite: false
        })
      );
      wall.rotation.y = Math.PI / 2;
      wall.rotation.z = Math.PI / 2;
      wall.position.set(side * 9.85, 1.0, -270);
      this.scene.add(wall);
    }
  }

  _buildArches() {
    this.arches = [];
    const metal = new THREE.MeshStandardMaterial({ color: 0x1a1336, roughness: 0.4, metalness: 0.75 });
    const cyan = new THREE.MeshBasicMaterial({ color: 0x52f7ff });
    const geoPillar = new THREE.BoxGeometry(0.7, 4.6, 0.7);
    const geoBar = new THREE.BoxGeometry(21.6, 0.28, 0.5);
    const geoLight = new THREE.BoxGeometry(11, 0.08, 0.22);
    const barMat = new THREE.MeshStandardMaterial({ color: 0x241a45, roughness: 0.4, metalness: 0.65, emissive: 0x1b0c4a, emissiveIntensity: 0.6 });

    for (let i = 0; i < 13; i++) {
      const g = new THREE.Group();
      const left = new THREE.Mesh(geoPillar, metal);
      left.position.set(-10.9, 2.3, 0);
      const right = new THREE.Mesh(geoPillar, metal);
      right.position.set(10.9, 2.3, 0);
      const bar = new THREE.Mesh(geoBar, barMat);
      bar.position.set(0, 4.5, 0);
      const light = new THREE.Mesh(geoLight, i % 2 ? cyan : new THREE.MeshBasicMaterial({ color: 0xff6ac8 }));
      light.position.set(0, 4.32, 0);
      g.add(left, right, bar, light);

      const halo = new THREE.Sprite(new THREE.SpriteMaterial({
        map: radialTexture(i % 2 ? 'rgba(62,246,255,.55)' : 'rgba(255,62,165,.5)', 'rgba(0,0,0,0)', 128),
        transparent: true,
        blending: THREE.AdditiveBlending,
        depthWrite: false
      }));
      halo.position.set(0, 4.3, 0);
      halo.scale.set(26, 5, 1);
      g.add(halo);

      g.position.z = 18 - i * 30;
      this.scene.add(g);
      this.arches.push({ group: g, index: i });
    }
    this.archSpan = 13 * 30;
  }

  _buildScenery() {
    this.islands = [];
    const rockMat = new THREE.MeshStandardMaterial({ color: 0x18112f, roughness: 0.9, metalness: 0.2, flatShading: true });
    const ringMats = [0xff3ea5, 0x3ef6ff, 0x8c5cff, 0xa7ff4f];
    for (let i = 0; i < 14; i++) {
      const side = i % 2 === 0 ? -1 : 1;
      const g = new THREE.Group();
      const rock = new THREE.Mesh(new THREE.DodecahedronGeometry(3 + Math.random() * 3, 0), rockMat);
      rock.scale.set(1.5, 0.8 + Math.random() * 0.7, 1.4);
      g.add(rock);
      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(4.2, 0.09, 6, 40),
        new THREE.MeshBasicMaterial({ color: ringMats[i % ringMats.length], transparent: true, opacity: 0.7, blending: THREE.AdditiveBlending })
      );
      ring.rotation.x = Math.PI / 2;
      ring.position.y = -1.6;
      g.add(ring);
      g.position.set(side * (20 + Math.random() * 34), -2 + Math.random() * 9, 20 - i * 34);
      g.userData.baseY = g.position.y;
      g.userData.phase = Math.random() * 6;
      g.userData.ring = ring;
      this.scene.add(g);
      this.islands.push(g);
    }

    // skyline
    this.buildings = [];
    const texA = makeBuildingTexture(280);
    const texB = makeBuildingTexture(330);
    const mats = [
      new THREE.MeshBasicMaterial({ map: texA, color: 0x9a8cff, transparent: true, opacity: 0.9, side: THREE.DoubleSide }),
      new THREE.MeshBasicMaterial({ map: texB, color: 0xff8bd6, transparent: true, opacity: 0.8, side: THREE.DoubleSide })
    ];
    for (let i = 0; i < 20; i++) {
      const mat = mats[i % 2];
      const h = 12 + Math.random() * 34;
      const b = new THREE.Mesh(new THREE.BoxGeometry(6 + Math.random() * 9, h, 6 + Math.random() * 9), mat);
      const side = i % 2 === 0 ? -1 : 1;
      b.position.set(side * (34 + Math.random() * 55), h / 2 - 7, 10 - i * 24);
      b.rotation.y = Math.random() * 0.6;
      this.scene.add(b);
      this.buildings.push(b);
    }
  }

  _buildDust() {
    const count = 260;
    const pos = new Float32Array(count * 3);
    const col = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      pos[i * 3] = (Math.random() - 0.5) * 44;
      pos[i * 3 + 1] = 0.3 + Math.random() * 14;
      pos[i * 3 + 2] = 30 - Math.random() * 260;
      const c = new THREE.Color().setHSL(0.5 + Math.random() * 0.35, 0.8, 0.65);
      col[i * 3] = c.r; col[i * 3 + 1] = c.g; col[i * 3 + 2] = c.b;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    this.dust = new THREE.Points(geo, new THREE.PointsMaterial({
      size: 0.16, vertexColors: true, transparent: true, opacity: 0.55,
      blending: THREE.AdditiveBlending, depthWrite: false
    }));
    this.dust.frustumCulled = false;
    this.scene.add(this.dust);
    this.dustPos = pos;
  }

  _buildLights() {
    const hemi = new THREE.HemisphereLight(0x9d8bff, 0x180b2b, 1.55);
    this.scene.add(hemi);
    const key = new THREE.DirectionalLight(0xffc49a, 2.7);
    key.position.set(-28, 42, 18);
    this.scene.add(key);
    const rim = new THREE.DirectionalLight(0x54e8ff, 1.6);
    rim.position.set(24, 18, -42);
    this.scene.add(rim);
    const fill = new THREE.PointLight(0x8c5cff, 45, 60, 1.6);
    fill.position.set(0, 8, 12);
    this.scene.add(fill);
    this.fill = fill;
  }

  update(dt, distance, speed, time, camera) {
    // scrolling road
    this.trackTex.offset.y = (distance * 0.047) % 1;
    this.grid.material.map.offset.y = (distance * 0.012) % 1;
    this.grid.material.map.offset.x = (distance * 0.004) % 1;

    // arches recycle
    const move = speed * dt;
    for (const a of this.arches) {
      a.group.position.z += move;
      if (a.group.position.z > 34) a.group.position.z -= this.archSpan;
    }

    // islands and buildings parallax
    for (const g of this.islands) {
      g.position.z += move * 0.22;
      g.position.y = g.userData.baseY + Math.sin(time * 0.7 + g.userData.phase) * 0.7;
      g.userData.ring.rotation.z = time * 0.35 + g.userData.phase;
      if (g.position.z > 50) g.position.z -= 480;
    }
    for (const b of this.buildings) {
      b.position.z += move * 0.12;
      if (b.position.z > 60) b.position.z -= 490;
    }

    // clouds drift
    for (const c of this.clouds) {
      c.sprite.position.x += dt * c.drift;
      if (c.sprite.position.x > 250) c.sprite.position.x = -250;
    }
    this.stars.rotation.y += dt * 0.006;
    this.sun.material.opacity = 0.9 + Math.sin(time * 0.9) * 0.05;

    // floating dust
    const pos = this.dustPos;
    for (let i = 0; i < pos.length; i += 3) {
      pos[i + 2] += move * (0.6 + ((i / 3) % 10) * 0.035);
      if (pos[i + 2] > 34) {
        pos[i + 2] -= 290;
        pos[i] = (Math.random() - 0.5) * 44;
      }
    }
    this.dust.geometry.attributes.position.needsUpdate = true;

    if (this.fill) {
      this.fill.intensity = 38 + Math.sin(time * 3.2) * 8;
    }
    this.sky.rotation.y = time * 0.003;
  }
}

import * as THREE from 'three';
import { textTexture, radialTexture } from './fx.js';
import { Crowd, CountBanner } from './crowd.js';

/* ------------ shared resources ------------ */
const geoCache = new Map();
const matCache = new Map();

function boxGeo(w, h, d) {
  const k = `box|${w}|${h}|${d}`;
  if (!geoCache.has(k)) geoCache.set(k, new THREE.BoxGeometry(w, h, d));
  return geoCache.get(k);
}

function planeGeo(w, h) {
  const k = `plane|${w}|${h}`;
  if (!geoCache.has(k)) geoCache.set(k, new THREE.PlaneGeometry(w, h));
  return geoCache.get(k);
}

function basicMat(color, { opacity = 1, transparent = false, additive = false, side = THREE.FrontSide } = {}) {
  const k = `basic|${color}|${opacity}|${transparent}|${additive}|${side}`;
  if (!matCache.has(k)) {
    matCache.set(k, new THREE.MeshBasicMaterial({
      color,
      opacity,
      transparent,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      depthWrite: !transparent,
      side
    }));
  }
  return matCache.get(k);
}

function standardMat(color, emissive = 0x000000, emissiveIntensity = 0.4, metalness = 0.5, roughness = 0.45) {
  const k = `std|${color}|${emissive}|${emissiveIntensity}|${metalness}|${roughness}`;
  if (!matCache.has(k)) {
    matCache.set(k, new THREE.MeshStandardMaterial({
      color, emissive, emissiveIntensity, metalness, roughness
    }));
  }
  return matCache.get(k);
}

function glowSprite(color, scale = 4, opacity = 0.6) {
  const rgba = new THREE.Color(color);
  const inner = `rgba(${Math.round(rgba.r * 255)},${Math.round(rgba.g * 255)},${Math.round(rgba.b * 255)},0.55)`;
  const mat = new THREE.SpriteMaterial({
    map: radialTexture(inner, 'rgba(0,0,0,0)', 128),
    transparent: true,
    opacity,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });
  const s = new THREE.Sprite(mat);
  s.scale.set(scale, scale, 1);
  return s;
}

const labelMatCache = new Map();
function labelMaterial(text, opts) {
  const key = `${text}|${opts.color}|${opts.sub || ''}|${opts.bg || ''}|${opts.border || ''}|${opts.size || ''}`;
  if (!labelMatCache.has(key)) {
    labelMatCache.set(key, new THREE.MeshBasicMaterial({
      map: textTexture(text, opts),
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      opacity: opts.opacity ?? 1
    }));
  }
  return labelMatCache.get(key);
}

const spriteLabelCache = new Map();
function spriteLabel(text, opts = {}) {
  const key = `${text}|${opts.color || '#fff'}|${opts.sub || ''}|${opts.size || ''}`;
  if (!spriteLabelCache.has(key)) {
    const mat = new THREE.SpriteMaterial({
      map: textTexture(text, {
        color: opts.color || '#ffffff',
        glow: opts.glow || 'rgba(255,255,255,.75)',
        size: opts.size || 150,
        sub: opts.sub || '',
        width: 512,
        height: opts.sub ? 300 : 256
      }),
      transparent: true,
      depthWrite: false,
      depthTest: false
    });
    spriteLabelCache.set(key, mat);
  }
  const s = new THREE.Sprite(spriteLabelCache.get(key).clone());
  s.material.map = spriteLabelCache.get(key).map;
  return s;
}

/* ---------------- GATES ---------------- */
export function gateOps(distance, luck = 0, count = 10) {
  const bothGood = Math.random() < 0.62 + luck * 0.03;
  const addA = Math.max(6, Math.round(((8 + Math.random() * 10) * (1 + distance / 1400)) / 2) * 2);
  const addB = Math.max(6, Math.round(((10 + Math.random() * 16) * (1 + distance / 1600)) / 2) * 2);
  const mulA = Math.random() < 0.48 ? 3 : 2;
  const mulB = Math.random() < 0.25 ? 3 : 2;

  const good = () => {
    if (Math.random() < 0.55) return { kind: 'mul', value: Math.random() < 0.3 ? 3 : 2, positive: true };
    return { kind: 'add', value: Math.max(5, Math.round(addA / 5) * 5), positive: true };
  };
  const bad = () => {
    const roll = Math.random();
    if (roll < 0.35) return { kind: 'div', value: 2, positive: false };
    if (roll < 0.65) return { kind: 'mul', value: 0.5, positive: false };
    return { kind: 'sub', value: Math.max(5, Math.round(Math.min(count * 0.3 + 4, addB) / 5) * 5), positive: false };
  };

  let left, right;
  if (bothGood) {
    left = Math.random() < 0.5 ? { kind: 'mul', value: mulA, positive: true } : { kind: 'add', value: Math.max(5, Math.round(addA / 5) * 5), positive: true };
    right = Math.random() < 0.5 ? { kind: 'mul', value: mulB, positive: true } : { kind: 'add', value: Math.max(5, Math.round(addB / 5) * 5), positive: true };
    if (left.kind === right.kind && left.value === right.value) right.value += right.kind === 'mul' ? 1 : 5;
  } else if (Math.random() < 0.5) {
    left = good();
    right = bad();
  } else {
    left = bad();
    right = good();
  }
  return { left, right };
}

export function opLabel(op) {
  if (op.kind === 'mul') return `×${op.value}`;
  if (op.kind === 'div') return `÷${op.value}`;
  if (op.kind === 'add') return `+${op.value}`;
  if (op.kind === 'sub') return `−${op.value}`;
  return '?';
}

export function applyOp(count, op) {
  if (op.kind === 'mul') return Math.floor(count * op.value);
  if (op.kind === 'div') return Math.floor(count / op.value);
  if (op.kind === 'add') return count + op.value;
  if (op.kind === 'sub') return count - op.value;
  return count;
}

export class Gate {
  constructor(scene, z, ops) {
    this.scene = scene;
    this.kind = 'gate';
    this.z = z;
    this.x = 0;
    this.ops = ops;
    this.passed = false;
    this.passAnim = 0;
    this.group = new THREE.Group();
    this.group.position.z = z;

    const frameColors = {
      good: { color: 0x8dffcf, emissive: 0x0f3a2a },
      bad: { color: 0xff6b8a, emissive: 0x3a0f1c }
    };

    // structural frame across the track
    const frameMat = standardMat(0x1a1338, 0x24124f, 0.7, 0.7, 0.35);
    const beamTop = new THREE.Mesh(boxGeo(19.4, 0.34, 0.55), frameMat);
    beamTop.position.set(0, 4.5, 0);
    this.group.add(beamTop);
    const beamBottom = new THREE.Mesh(boxGeo(19.4, 0.16, 0.4), frameMat);
    beamBottom.position.set(0, 0.1, 0);
    this.group.add(beamBottom);
    for (const x of [-9.2, 0, 9.2]) {
      const post = new THREE.Mesh(boxGeo(0.34, 4.6, 0.55), frameMat);
      post.position.set(x, 2.3, 0);
      this.group.add(post);
      const light = new THREE.Mesh(boxGeo(0.1, 4.2, 0.1), basicMat(x === 0 ? 0xffffff : 0x9d7dff, { transparent: true, opacity: 0.65 }));
      light.position.set(x, 2.3, 0.31);
      this.group.add(light);
    }

    // two panels
    this.panels = {};
    const sides = [
      { key: 'left', op: ops.left, x: -4.7, sign: -1 },
      { key: 'right', op: ops.right, x: 4.7, sign: 1 }
    ];
    for (const side of sides) {
      const positive = side.op.positive;
      const color = positive ? 0xa7ff4f : 0xff4d7a;
      const bg = positive ? 'rgba(7, 26, 18, 0.78)' : 'rgba(32, 5, 16, 0.8)';
      const border = positive ? 'rgba(167,255,79,0.95)' : 'rgba(255,77,122,0.95)';
      const sub = side.op.kind === 'mul' ? 'MOB MULTIPLY'
        : side.op.kind === 'add' ? 'RECRUITS'
        : side.op.kind === 'div' ? 'MOB LOSS' : 'MOB LOSS';
      const tex = textTexture(opLabel(side.op), {
        color: positive ? '#d8ff9b' : '#ffb3c5',
        glow: positive ? 'rgba(167,255,79,.9)' : 'rgba(255,77,122,.9)',
        size: 195,
        sub,
        subColor: positive ? 'rgba(220,255,190,.8)' : 'rgba(255,190,205,.8)',
        bg,
        border,
        width: 700,
        height: 460
      });
      const mat = new THREE.MeshBasicMaterial({
        map: tex,
        transparent: true,
        depthWrite: false,
        side: THREE.DoubleSide
      });
      const panel = new THREE.Mesh(planeGeo(9.0, 4.1), mat);
      panel.position.set(side.x, 2.42, 0.02);
      this.group.add(panel);

      const glow = glowSprite(color, 11, 0.28);
      glow.position.set(side.x, 2.3, -0.3);
      glow.scale.set(10.4, 5.4, 1);
      this.group.add(glow);

      const floorLine = new THREE.Mesh(
        planeGeo(8.4, 0.5),
        basicMat(color, { transparent: true, opacity: 0.7, additive: true })
      );
      floorLine.rotation.x = -Math.PI / 2;
      floorLine.position.set(side.x, 0.035, 0.3);
      this.group.add(floorLine);

      this.panels[side.key] = { mesh: panel, glow, floorLine, op: side.op, color };
    }

    // hovering instruction chevrons
    const chev = spriteLabel('PICK A GATE', { color: '#d9cfff', glow: 'rgba(140,92,255,.7)', size: 92 });
    chev.position.set(0, 5.4, 0);
    chev.scale.set(5.4, 2.7, 1);
    chev.material.opacity = 0.7;
    this.group.add(chev);
    this.chev = chev;

    scene.add(this.group);
  }

  panelAt(x) {
    return x < 0 ? this.panels.left : this.panels.right;
  }

  markPassed() {
    this.passed = true;
    this.passAnim = 0.001;
    for (const key of ['left', 'right']) {
      const p = this.panels[key];
      p.mesh.visible = false;
    }
    this.chev.visible = false;
  }

  update(dt, time) {
    for (const key of ['left', 'right']) {
      const p = this.panels[key];
      if (!p.mesh.visible) continue;
      const pulse = 0.86 + Math.sin(time * 3 + (key === 'left' ? 0 : 1.7)) * 0.08;
      p.mesh.material.opacity = pulse;
      p.floorLine.material.opacity = 0.5 + Math.sin(time * 5 + (key === 'left' ? 0 : 2)) * 0.2;
    }
    if (this.passAnim > 0) {
      this.passAnim += dt;
      this.group.position.y = Math.sin(this.passAnim * 14) * 0.04;
      if (this.passAnim > 0.45) {
        this.group.visible = false;
      }
    }
    if (this.chev.visible) {
      this.chev.position.y = 5.4 + Math.sin(time * 2.2) * 0.12;
    }
  }
}

/* ---------------- HAZARDS ---------------- */
export function createSaw(scene, z, { lane = 0, sweep = 2.4, phase = 0 } = {}) {
  const group = new THREE.Group();
  group.position.set(lane, 0, z);

  const metal = standardMat(0x9d1832, 0xff2f4a, 0.55, 0.85, 0.28);
  const hot = basicMat(0xff6a7f, { transparent: true, opacity: 0.9 });
  const disc = new THREE.Mesh(new THREE.CylinderGeometry(1.22, 1.22, 0.16, 14), metal);
  disc.rotation.x = Math.PI / 2;
  disc.position.y = 1.42;
  group.add(disc);

  const inner = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.42, 0.2, 10), hot);
  inner.rotation.x = Math.PI / 2;
  inner.position.y = 1.42;
  group.add(inner);

  const spinner = new THREE.Group();
  spinner.position.y = 1.42;
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * Math.PI * 2;
    const tooth = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.55, 4), metal);
    tooth.position.set(Math.cos(a) * 1.36, Math.sin(a) * 1.36, 0);
    tooth.rotation.z = a - Math.PI / 2;
    spinner.add(tooth);
  }
  group.add(spinner);

  // warning column
  const beam = new THREE.Mesh(
    boxGeo(0.16, 3.0, 0.16),
    basicMat(0xff3355, { transparent: true, opacity: 0.35, additive: true })
  );
  beam.position.y = 1.1;
  group.add(beam);

  // ground warning
  const warning = new THREE.Mesh(
    new THREE.RingGeometry(1.1, 1.75, 24),
    basicMat(0xff3355, { transparent: true, opacity: 0.55, additive: true, side: THREE.DoubleSide })
  );
  warning.rotation.x = -Math.PI / 2;
  warning.position.y = 0.03;
  group.add(warning);

  const glow = glowSprite(0xff2f4a, 6, 0.45);
  glow.position.y = 1.42;
  group.add(glow);

  // floating danger chevrons on the ground ahead
  const decal = new THREE.Mesh(
    planeGeo(3.4, 2.4),
    new THREE.MeshBasicMaterial({
      map: textTexture('!', { color: '#ff9db0', glow: 'rgba(255,47,74,.9)', size: 200, width: 256, height: 256 }),
      transparent: true, depthWrite: false, opacity: 0.55
    })
  );
  decal.rotation.x = -Math.PI / 2;
  decal.position.set(0, 0.04, 2.0);
  group.add(decal);

  scene.add(group);

  return {
    kind: 'saw',
    group,
    z,
    x: lane,
    data: { lane, sweep, phase, cooldown: 0, hitFlash: 0 },
    radius: 1.5,
    update(dt, time) {
      this.data.hitFlash = Math.max(0, this.data.hitFlash - dt);
      const wobble = Math.sin(time * 2.1 + phase);
      this.x = lane + wobble * sweep;
      group.position.x = this.x;
      spinner.rotation.z = time * 9;
      disc.rotation.z = time * 9;
      warning.material.opacity = 0.35 + Math.abs(Math.sin(time * 4 + phase)) * 0.35;
      glow.material.opacity = 0.32 + Math.abs(wobble) * 0.25;
      if (this.data.hitFlash > 0) {
        group.position.x += Math.sin(time * 70) * 0.12;
      }
    }
  };
}

export function createLaser(scene, z, side = 1) {
  const group = new THREE.Group();
  const center = side * 5.0;
  const width = 8.6;
  group.position.set(center, 0, z);

  const postMat = standardMat(0x251632, 0x4c0b20, 0.7, 0.8, 0.3);
  for (const dx of [-width / 2, width / 2]) {
    const post = new THREE.Mesh(boxGeo(0.35, 4.2, 0.5), postMat);
    post.position.set(dx, 2.1, 0);
    group.add(post);
    const cap = new THREE.Mesh(boxGeo(0.55, 0.22, 0.6), basicMat(0xff3355, { transparent: true, opacity: 0.9 }));
    cap.position.set(dx, 4.25, 0);
    group.add(cap);
  }
  const top = new THREE.Mesh(boxGeo(width, 0.16, 0.3), basicMat(0xff3355, { transparent: true, opacity: 0.75 }));
  top.position.set(0, 4.15, 0);
  group.add(top);

  const beams = [];
  for (let i = 0; i < 5; i++) {
    const beam = new THREE.Mesh(
      new THREE.CylinderGeometry(0.055, 0.055, 3.9, 6),
      basicMat(0xff3355, { transparent: true, opacity: 0.8, additive: true })
    );
    beam.position.set(-width / 2 + 0.55 + i * ((width - 1.1) / 4), 2.08, 0);
    group.add(beam);
    beams.push(beam);
  }

  const wall = new THREE.Mesh(
    planeGeo(width - 0.4, 3.8),
    new THREE.MeshBasicMaterial({
      map: radialTexture('rgba(255,51,85,0.28)', 'rgba(255,51,85,0)', 128),
      transparent: true,
      opacity: 0.65,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      side: THREE.DoubleSide
    })
  );
  wall.position.set(0, 2.05, 0);
  group.add(wall);

  const floor = new THREE.Mesh(
    planeGeo(width, 2.4),
    new THREE.MeshBasicMaterial({
      map: textTexture('DANGER', { color: '#ff7d95', glow: 'rgba(255,51,85,.85)', size: 90, width: 512, height: 128 }),
      transparent: true, depthWrite: false, opacity: 0.55
    })
  );
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(0, 0.04, 2.1);
  group.add(floor);

  scene.add(group);
  const xMin = center - width / 2;
  const xMax = center + width / 2;

  return {
    kind: 'laser',
    group,
    z,
    x: center,
    data: { side, xMin, xMax, cooldown: 0, phase: Math.random() * 6 },
    radius: width / 2,
    update(dt, time) {
      this.data.cooldown = Math.max(0, this.data.cooldown - dt);
      const f = 0.6 + Math.abs(Math.sin(time * 11 + this.data.phase)) * 0.35;
      wall.material.opacity = 0.35 + f * 0.35;
      for (let i = 0; i < beams.length; i++) {
        beams[i].material.opacity = 0.55 + Math.abs(Math.sin(time * 16 + i)) * 0.4;
        beams[i].scale.x = 0.8 + Math.abs(Math.sin(time * 9 + i)) * 0.9;
      }
      top.material.opacity = f;
    }
  };
}

