67:     if (!this.ctx || this.muted) return;
68:     const t = this.now() + delay;
69:     const len = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
70:     const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
71:     const data = buffer.getChannelData(0);
72:     for (let i = 0; i < len; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / len);
73:     const source = this.ctx.createBufferSource();
74:     source.buffer = buffer;
75:     const biquad = this.ctx.createBiquadFilter();
76:     biquad.type = type;
77:     biquad.frequency.setValueAtTime(filter, t);
78:     biquad.Q.value = q;
79:     const g = this.ctx.createGain();
80:     g.gain.setValueAtTime(gain, t);
81:     g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
82:     source.connect(biquad);
83:     biquad.connect(g);
84:     g.connect(this.sfxGain);
85:     source.start(t);
86:   }
