173:     if (!this.ctx || this.muted) return;
174:     const step = this.musicStep++;
175:     // Slow minor-key synthwave arpeggio.
176:     const roots = [110, 110, 130.81, 98];
177:     const root = roots[Math.floor(step / 8) % roots.length];
178:     const pattern = [0, 7, 12, 15, 19, 15, 12, 7];
179:     const semi = pattern[step % 8];
