182:     if (step % 8 === 0) {
183:       this.tone({ freq: root / 2, dur: 1.8, type: 'sine', gain: 0.07, dest: this.musicGain, attack: 0.12 });
184:       this.tone({ freq: root * 1.5, dur: 1.4, type: 'sine', gain: 0.025, dest: this.musicGain, attack: 0.2 });
185:     }
186:     if (step % 4 === 2) {
187:       this.noise({ dur: 0.04, gain: 0.022, filter: 7000, type: 'highpass' });
188:     }
189:   }
190: }

