.battle-vs { color: rgba(255,255,255,.3); font-size: 8px; letter-spacing: .2em; }

/* ---- boss HUD --------------------------------------------------- */
.boss-hud {
  position: absolute;
  left: 50%;
  top: calc(84px + var(--safe-t));
  transform: translateX(-50%);
  width: min(560px, calc(100vw - 30px));
  padding: 9px 14px 8px;
  border-radius: 14px;
  border: 1px solid rgba(255, 62, 108, 0.45);
  background: linear-gradient(180deg, rgba(34, 5, 18, 0.82), rgba(12, 4, 14, 0.78));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 8px 30px rgba(0,0,0,.5), 0 0 32px rgba(255,47,90,.16), inset 0 1px 0 rgba(255,255,255,.08);
  animation: boss-hud-in .32s cubic-bezier(.2,.9,.3,1.2) both;
}
@keyframes boss-hud-in { from { opacity: 0; transform: translate(-50%, -10px) scale(.97); } to { opacity: 1; transform: translate(-50%, 0) scale(1); } }
.boss-top { display: flex; align-items: center; gap: 10px; margin-bottom: 7px; }
.boss-tag {
  display: inline-flex; align-items: center; gap: 5px;
  color: #ff8fa4; font-size: 8px; font-weight: 900; letter-spacing: .22em;
}
.boss-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: #ff2f5a; box-shadow: 0 0 9px #ff2f5a;
  animation: boss-dot 1.1s ease-in-out infinite;
}
@keyframes boss-dot { 0%,100% { opacity: .45; transform: scale(.8); } 50% { opacity: 1; transform: scale(1.15); } }
.boss-name {
  flex: 1; min-width: 0;
  color: #ffe0e7; font-size: 13px; font-weight: 900; letter-spacing: .1em;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  text-shadow: 0 0 18px rgba(255,47,90,.45);
}
.boss-phase {
  color: #ff90a6; font-size: 8px; font-weight: 900; letter-spacing: .18em;
  padding: 3px 7px; border-radius: 99px;
  border: 1px solid rgba(255,62,108,.3); background: rgba(255,47,90,.1);
}
.boss-track {
  height: 11px; border-radius: 8px; overflow: hidden;
  background: #2a0712; border: 1px solid rgba(255,47,90,.22);
  box-shadow: inset 0 1px 4px rgba(0,0,0,.6);
}
.boss-fill {
  height: 100%; width: 100%;
  background: linear-gradient(90deg, #ff2f4e, #ff8a5c 62%, #ffc07a);
  box-shadow: 0 0 16px rgba(255,62,108,.75), inset 0 1px 0 rgba(255,255,255,.35);
  transition: width .1s linear;
  position: relative;
}
.boss-fill::after {
  content: ''; position: absolute; inset: 0;
  background: repeating-linear-gradient(115deg, rgba(255,255,255,.16) 0 8px, transparent 8px 18px);
  animation: boss-stripes 1.2s linear infinite;
  opacity: .45;
}
@keyframes boss-stripes { to { background-position: 36px 0; } }
.boss-bottom {
  display: flex; align-items: center; justify-content: space-between;
  margin-top: 5px; color: rgba(255,190,202,.75);
  font-size: 7.5px; font-weight: 800; letter-spacing: .16em;
  font-variant-numeric: tabular-nums;
}
.boss-tip { color: rgba(255,255,255,.32); letter-spacing: .18em; }
.boss-hud[data-phase="2"] { border-color: rgba(255,154,62,.5); box-shadow: 0 8px 30px rgba(0,0,0,.5), 0 0 34px rgba(255,122,40,.2), inset 0 1px 0 rgba(255,255,255,.08); }
.boss-hud[data-phase="2"] .boss-fill { background: linear-gradient(90deg,#ff7a2f,#ffb347 62%,#ffe08a); box-shadow: 0 0 18px rgba(255,154,62,.75); }
.boss-hud[data-phase="2"] .boss-tag, .boss-hud[data-phase="2"] .boss-phase { color: #ffbe7a; }
.boss-hud[data-phase="2"] .boss-dot { background: #ff9a3e; box-shadow: 0 0 9px #ff9a3e; }
.boss-hud[data-phase="3"] { border-color: rgba(255,47,47,.62); animation: boss-hud-in .32s cubic-bezier(.2,.9,.3,1.2) both, boss-danger .9s ease-in-out infinite; }
@keyframes boss-danger { 0%,100% { box-shadow: 0 8px 30px rgba(0,0,0,.5), 0 0 30px rgba(255,20,20,.2); } 50% { box-shadow: 0 8px 30px rgba(0,0,0,.5), 0 0 46px rgba(255,20,20,.42); } }
.boss-hud[data-phase="3"] .boss-fill { background: linear-gradient(90deg,#ff1414,#ff4d3d 62%,#ffb36b); box-shadow: 0 0 20px rgba(255,30,30,.85); }
.boss-hud[data-phase="3"] .boss-tag, .boss-hud[data-phase="3"] .boss-phase { color: #ff8d8d; }
.boss-hud[data-phase="3"] .boss-dot { background: #ff2020; box-shadow: 0 0 10px #ff2020; }

/* ---- boss warning ---------------------------------------------- */
.boss-warning {
  position: fixed;
  inset: 0;
  z-index: 70;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  pointer-events: none;
  text-align: center;
  background: radial-gradient(ellipse at center, rgba(96, 0, 22, .5), rgba(30, 0, 10, .16) 42%, transparent 68%);
  animation: bw-in 2.5s cubic-bezier(.2,.8,.2,1) both;
}
.boss-warning.is-hidden { display: none; }
@keyframes bw-in {
  0% { opacity: 0; transform: scale(.96); }
  8% { opacity: 1; transform: scale(1); }
  16% { opacity: .55; }
  22% { opacity: 1; }
  76% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.03); }
}
.bw-kicker {
  display: flex; align-items: center; gap: 12px;
  color: #ff7a91; font-size: 10px; font-weight: 900; letter-spacing: .48em;
  text-shadow: 0 0 14px rgba(255,47,90,.8);
}
.bw-kicker i { display: block; width: clamp(28px, 6vw, 62px); height: 1px; background: linear-gradient(90deg, transparent, #ff4d6a); }
.bw-kicker i:last-child { background: linear-gradient(90deg, #ff4d6a, transparent); }
.boss-warning strong {
  font-size: clamp(30px, 6.6vw, 74px);
  font-weight: 900;
  letter-spacing: .05em;
  line-height: .98;
  color: #fff4f6;
  text-shadow: 0 0 22px rgba(255,47,90,.8), 0 0 60px rgba(255,20,70,.45), 0 3px 0 rgba(90,0,20,.65);
}
.bw-sub {
  color: rgba(255,170,190,.82); font-size: 9px; font-weight: 900; letter-spacing: .5em;
  text-shadow: 0 0 12px rgba(255,47,90,.7);
}

