+}
+.boss-dot {
+  width: 6px; height: 6px; border-radius: 50%;
+  background: #ff2f5a; box-shadow: 0 0 9px #ff2f5a;
+  animation: boss-dot 1.1s ease-in-out infinite;
+}
+@keyframes boss-dot { 0%,100% { opacity: .45; transform: scale(.8); } 50% { opacity: 1; transform: scale(1.15); } }
+.boss-name {
+  flex: 1; min-width: 0;
+  color: #ffe0e7; font-size: 13px; font-weight: 900; letter-spacing: .1em;
