+  opacity: .45;
+}
+@keyframes boss-stripes { to { background-position: 36px 0; } }
+.boss-bottom {
+  display: flex; align-items: center; justify-content: space-between;
+  margin-top: 5px; color: rgba(255,190,202,.75);
+  font-size: 7.5px; font-weight: 800; letter-spacing: .16em;
+  font-variant-numeric: tabular-nums;
+}
+.boss-tip { color: rgba(255,255,255,.32); letter-spacing: .18em; }
+.boss-hud[data-phase="2"] { border-color: rgba(255,154,62,.5); box-shadow: 0 8px 30px rgba(0,0,0,.5), 0 0 34px rgba(255,122,40,.2), inset 0 1px 0 rgba(255,255,255,.08); }
+.boss-hud[data-phase="2"] .boss-fill { background: linear-gradient(90deg,#ff7a2f,#ffb347 62%,#ffe08a); box-shadow: 0 0 18px rgba(255,154,62,.75); }
+.boss-hud[data-phase="2"] .boss-tag, .boss-hud[data-phase="2"] .boss-phase { color: #ffbe7a; }
+.boss-hud[data-phase="2"] .boss-dot { background: #ff9a3e; box-shadow: 0 0 9px #ff9a3e; }
+.boss-hud[data-phase="3"] { border-color: rgba(255,47,47,.62); animation: boss-hud-in .32s cubic-bezier(.2,.9,.3,1.2) both, boss-danger .9s ease-in-out infinite; }
+@keyframes boss-danger { 0%,100% { box-shadow: 0 8px 30px rgba(0,0,0,.5), 0 0 30px rgba(255,20,20,.2); } 50% { box-shadow: 0 8px 30px rgba(0,0,0,.5), 0 0 46px rgba(255,20,20,.42); } }
+.boss-hud[data-phase="3"] .boss-fill { background: linear-gradient(90deg,#ff1414,#ff4d3d 62%,#ffb36b); box-shadow: 0 0 20px rgba(255,30,30,.85); }
